function fieldTexture() {
  return canvasTexture(960, 1242, (ctx, w, h) => {
    // base
    const base = ctx.createLinearGradient(0, 0, 0, h);
    base.addColorStop(0, '#0b1c20');
    base.addColorStop(0.5, '#08191b');
    base.addColorStop(1, '#0b1c20');
    ctx.fillStyle = base;
    ctx.fillRect(0, 0, w, h);

    // mowed stripes
    for (let i = 0; i < 22; i++) {
      if (i % 2) continue;
      ctx.fillStyle = 'rgba(120, 215, 190, 0.022)';
      ctx.fillRect(0, (i / 22) * h, w, h / 22);
    }
    // fine grid
    ctx.strokeStyle = 'rgba(110, 190, 190, 0.045)';
    ctx.lineWidth = 1;
    for (let x = 0; x <= w; x += 48) { ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, h); ctx.stroke(); }
    for (let y = 0; y <= h; y += 48) { ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(w, y); ctx.stroke(); }

    // team end glows
    const bg = ctx.createLinearGradient(0, h, 0, h - 260);
    bg.addColorStop(0, 'rgba(34, 146, 255, 0.20)');
    bg.addColorStop(1, 'rgba(34, 146, 255, 0)');
    ctx.fillStyle = bg; ctx.fillRect(0, h - 260, w, 260);
    const og = ctx.createLinearGradient(0, 0, 0, 260);
    og.addColorStop(0, 'rgba(255, 116, 30, 0.20)');
    og.addColorStop(1, 'rgba(255, 116, 30, 0)');
    ctx.fillStyle = og; ctx.fillRect(0, 0, w, 260);

    const line = 'rgba(203, 240, 255, 0.62)';
    ctx.strokeStyle = line;
    ctx.lineWidth = 3.5;
    ctx.shadowColor = 'rgba(120, 220, 255, 0.4)';
    ctx.shadowBlur = 10;

    // boundary
    const m = 26;
    ctx.strokeRect(m, m, w - m * 2, h - m * 2);
    // halfway
    ctx.beginPath(); ctx.moveTo(m, h / 2); ctx.lineTo(w - m, h / 2); ctx.stroke();
    // center circle
    ctx.beginPath(); ctx.arc(w / 2, h / 2, 116, 0, Math.PI * 2); ctx.stroke();
    ctx.beginPath(); ctx.arc(w / 2, h / 2, 12, 0, Math.PI * 2); ctx.fillStyle = line; ctx.fill();

    // center faint emblem
    ctx.save();
    ctx.globalAlpha = 0.17;
    ctx.strokeStyle = '#9fe8ff';
    ctx.lineWidth = 2;
    for (let r = 150; r < 330; r += 45) {
      ctx.beginPath();
      ctx.arc(w / 2, h / 2, r, -0.35, 0.35);
      ctx.stroke();
      ctx.beginPath();
      ctx.arc(w / 2, h / 2, r, Math.PI - 0.35, Math.PI + 0.35);
      ctx.stroke();
    }
    ctx.restore();

    // goal boxes
    const boxW = 390, boxD = 152;
    ctx.strokeRect((w - boxW) / 2, m, boxW, boxD);
    ctx.strokeRect((w - boxW) / 2, h - m - boxD, boxW, boxD);
    // arcs
    ctx.beginPath(); ctx.arc(w / 2, m + boxD, 120, 0.2, Math.PI - 0.2); ctx.stroke();
    ctx.beginPath(); ctx.arc(w / 2, h - m - boxD, 120, Math.PI + 0.2, Math.PI * 2 - 0.2); ctx.stroke();

    // corner chevrons
    const corner = 104;
    ctx.strokeStyle = 'rgba(203, 240, 255, 0.36)';
    ctx.lineWidth = 2;
    [[m, m, 1, 1], [w - m, m, -1, 1], [m, h - m, 1, -1], [w - m, h - m, -1, -1]].forEach(([x, y, sx, sy]) => {
      ctx.beginPath();
      ctx.moveTo(x + sx * corner, y);
      ctx.lineTo(x, y);
      ctx.lineTo(x, y + sy * corner);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(x + sx * (corner - 18), y + sy * 18);
      ctx.lineTo(x + sx * 18, y + sy * 18);
      ctx.lineTo(x + sx * 18, y + sy * (corner - 18));
      ctx.stroke();
    });
    ctx.shadowBlur = 0;

    // mid-field logo lettering
    ctx.save();
    ctx.translate(w / 2, h / 2);
    ctx.rotate(0);
    ctx.font = '900 46px Orbitron, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillStyle = 'rgba(180, 235, 255, 0.09)';
    ctx.fillText('NEO LEAGUE', 0, -186);
    ctx.font = '700 22px Rajdhani, sans-serif';
    ctx.fillStyle = 'rgba(180, 235, 255, 0.10)';
    ctx.fillText('TURBO STRIKERS ARENA', 0, 212);
    ctx.restore();
  }, { anisotropy: 8 });
}

function skyTexture() {
  return canvasTexture(8, 512, (ctx, w, h) => {
    const g = ctx.createLinearGradient(0, 0, 0, h);
    g.addColorStop(0, '#01030a');
    g.addColorStop(0.42, '#061226');
    g.addColorStop(0.62, '#0b2140');
    g.addColorStop(0.76, '#123153');
    g.addColorStop(0.84, '#0a1a2e');
    g.addColorStop(1, '#03060c');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
  });
}

function makeNet(color) {
  const pts = [];
  const gx = 11, gy = FIELD.goalH, depth = FIELD.goalDepth;
  // back plane grid
  for (let x = -gx; x <= gx; x += 2.2) {
    pts.push(x, 0, depth, x, gy, depth);
  }
  for (let y = 0; y <= gy; y += 1.8) {
    pts.push(-gx, y, depth, gx, y, depth);
  }
  // top and sides
  for (let i = 0; i <= 5; i++) {
    const z = (i / 5) * depth;
    pts.push(-gx, gy, z, gx, gy, z);
    pts.push(-gx, 0, z, -gx, gy, z);
    pts.push(gx, 0, z, gx, gy, z);
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
  return new THREE.LineSegments(geo, new THREE.LineBasicMaterial({ color, transparent: true, opacity: 0.32 }));
}

export function buildArena(scene) {
  const group = new THREE.Group();
  scene.add(group);

  // ── sky dome ──────────────────────────────────────────────
  const sky = new THREE.Mesh(
    new THREE.SphereGeometry(240, 32, 20),
    new THREE.MeshBasicMaterial({ map: skyTexture(), side: THREE.BackSide, depthWrite: false })
  );
  group.add(sky);

  // stars
  const starCount = 900;
  const starPos = new Float32Array(starCount * 3);
  const starSizes = new Float32Array(starCount);
  for (let i = 0; i < starCount; i++) {
    const r = rand(100, 220);
    const theta = rand(0, Math.PI * 2);
    const phi = rand(0.02, Math.PI * 0.48);
    starPos[i * 3] = Math.cos(theta) * Math.cos(phi) * r;
    starPos[i * 3 + 1] = 8 + Math.sin(phi) * r * 0.9;
    starPos[i * 3 + 2] = Math.sin(theta) * Math.cos(phi) * r;
    starSizes[i] = rand(0.5, 1.8);
  }
  const starGeo = new THREE.BufferGeometry();
  starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
  starGeo.setAttribute('size', new THREE.BufferAttribute(starSizes, 1));
  const stars = new THREE.Points(starGeo, new THREE.PointsMaterial({
    color: 0xbfe8ff, size: 0.9, transparent: true, opacity: 0.65, sizeAttenuation: true, depthWrite: false,
  }));
  group.add(stars);

  // ── lights ────────────────────────────────────────────────
  scene.add(new THREE.HemisphereLight(0x8ccfff, 0x081018, 1.05));
  scene.add(new THREE.AmbientLight(0x31506b, 0.55));

  const sun = new THREE.DirectionalLight(0xeaf8ff, 2.1);
  sun.position.set(24, 54, 18);
  sun.castShadow = true;
  sun.shadow.mapSize.set(1536, 1536);
  sun.shadow.camera.left = -58;
  sun.shadow.camera.right = 58;
  sun.shadow.camera.top = 62;
  sun.shadow.camera.bottom = -62;
  sun.shadow.camera.near = 10;
  sun.shadow.camera.far = 130;
  sun.shadow.bias = -0.0007;
  sun.shadow.normalBias = 0.03;
  scene.add(sun);

  const blueLight = new THREE.PointLight(TEAM.blue.color, 95, 62, 2);
  blueLight.position.set(0, 14, -FIELD.halfL - 2);
  scene.add(blueLight);
  const orangeLight = new THREE.PointLight(TEAM.orange.color, 95, 62, 2);
  orangeLight.position.set(0, 14, FIELD.halfL + 2);
  scene.add(orangeLight);

  const fill1 = new THREE.PointLight(0x5ea8ff, 55, 85, 2);
  fill1.position.set(-22, 24, 0);
  scene.add(fill1);
  const fill2 = new THREE.PointLight(0xff8a4a, 40, 85, 2);
  fill2.position.set(24, 22, 8);
  scene.add(fill2);

  // ── pitch ─────────────────────────────────────────────────
  const pitch = new THREE.Mesh(
    new THREE.PlaneGeometry(FIELD.halfW * 2, FIELD.halfL * 2),
    new THREE.MeshStandardMaterial({ map: fieldTexture(), roughness: 0.82, metalness: 0.12 })
  );
  pitch.rotation.x = -Math.PI / 2;
  pitch.receiveShadow = true;
  group.add(pitch);

  // outer apron
  const apron = new THREE.Mesh(
    new THREE.PlaneGeometry(FIELD.halfW * 2 + 34, FIELD.halfL * 2 + 34),
    new THREE.MeshStandardMaterial({ color: 0x050d16, roughness: 0.9, metalness: 0.25 })
  );
  apron.rotation.x = -Math.PI / 2;
  apron.position.y = -0.16;
  apron.receiveShadow = true;
  group.add(apron);

  // glowing sidelines
  const lineMat = new THREE.MeshBasicMaterial({ color: 0x86e4ff, transparent: true, opacity: 0.85 });
  const sides = [
    { p: [0, 0.03, -FIELD.halfL], s: [FIELD.halfW * 2, 0.03, 0.18] },
    { p: [0, 0.03, FIELD.halfL], s: [FIELD.halfW * 2, 0.03, 0.18] },
    { p: [-FIELD.halfW, 0.03, 0], s: [0.18, 0.03, FIELD.halfL * 2] },
    { p: [FIELD.halfW, 0.03, 0], s: [0.18, 0.03, FIELD.halfL * 2] },
  ];
  sides.forEach(({ p, s }) => {
    const m = new THREE.Mesh(new THREE.BoxGeometry(...s), lineMat);
    m.position.set(...p);
    group.add(m);
  });

  // ── glass boundary walls ─────────────────────────────────
  const wallMatSide = new THREE.MeshPhysicalMaterial({
    color: 0x1f6d8c, transparent: true, opacity: 0.13, roughness: 0.08, metalness: 0.55,
    side: THREE.DoubleSide, depthWrite: false,
  });
  const edgeMat = new THREE.LineBasicMaterial({ color: 0x68d6ff, transparent: true, opacity: 0.36 });
  function addGlass(w, h, d, x, y, z, material = wallMatSide) {
    const geo = new THREE.BoxGeometry(w, h, d);
    const mesh = new THREE.Mesh(geo, material);
    mesh.position.set(x, y, z);
    group.add(mesh);
    const edges = new THREE.LineSegments(new THREE.EdgesGeometry(geo), edgeMat);
    edges.position.copy(mesh.position);
    group.add(edges);
    return mesh;
  }

  addGlass(0.32, FIELD.wallH, FIELD.halfL * 2, -FIELD.halfW, FIELD.wallH / 2, 0);
  addGlass(0.32, FIELD.wallH, FIELD.halfL * 2, FIELD.halfW, FIELD.wallH / 2, 0);

  const sideSegment = (FIELD.halfW * 2 - FIELD.goalHalfW * 2) / 2;
  const sideX = FIELD.goalHalfW + sideSegment / 2;
  const wallMatBlue = new THREE.MeshPhysicalMaterial({
    color: 0x1a5f9a, transparent: true, opacity: 0.17, roughness: 0.1, metalness: 0.5,
    side: THREE.DoubleSide, depthWrite: false,
  });
  const wallMatOrange = new THREE.MeshPhysicalMaterial({
    color: 0x9a4a17, transparent: true, opacity: 0.17, roughness: 0.1, metalness: 0.5,
    side: THREE.DoubleSide, depthWrite: false,
  });
  for (const sign of [-1, 1]) {
    const mat = sign < 0 ? wallMatBlue : wallMatOrange;
    const z = sign * FIELD.halfL;
    addGlass(sideSegment, FIELD.wallH, 0.32, -sideX, FIELD.wallH / 2, z, mat);
    addGlass(sideSegment, FIELD.wallH, 0.32, sideX, FIELD.wallH / 2, z, mat);
    addGlass(FIELD.goalHalfW * 2, FIELD.wallH - FIELD.goalH, 0.32, 0, FIELD.goalH + (FIELD.wallH - FIELD.goalH) / 2, z, mat);
  }

  // vertical ribs + top rail
  const ribMat = new THREE.MeshBasicMaterial({ color: 0x59cbff, transparent: true, opacity: 0.35 });
  const ribMatO = new THREE.MeshBasicMaterial({ color: 0xff9347, transparent: true, opacity: 0.35 });
  for (let z = -FIELD.halfL; z <= FIELD.halfL; z += 8) {
    for (const x of [-FIELD.halfW, FIELD.halfW]) {
      const rib = new THREE.Mesh(new THREE.BoxGeometry(0.22, FIELD.wallH, 0.22), x < 0 ? ribMat : ribMat);
      rib.position.set(x, FIELD.wallH / 2, z);
      group.add(rib);
    }
  }
  for (const x of [-FIELD.halfW, FIELD.halfW]) {
    const rail = new THREE.Mesh(new THREE.BoxGeometry(0.35, 0.22, FIELD.halfL * 2), ribMat);
    rail.position.set(x, FIELD.wallH, 0);
    group.add(rail);
  }
  for (const sign of [-1, 1]) {
    const mat = sign < 0 ? ribMat : ribMatO;
    const z = sign * FIELD.halfL;
    for (let x = -FIELD.halfW; x <= FIELD.halfW; x += 8) {
      if (Math.abs(x) < FIELD.goalHalfW) continue;
      const rib = new THREE.Mesh(new THREE.BoxGeometry(0.22, FIELD.wallH, 0.22), mat);
      rib.position.set(x, FIELD.wallH / 2, z);
      group.add(rib);
    }
    const rail = new THREE.Mesh(new THREE.BoxGeometry(FIELD.halfW * 2, 0.22, 0.35), mat);
    rail.position.set(0, FIELD.wallH, z);
    group.add(rail);
  }

  // ── goals ─────────────────────────────────────────────────
  const goalGlows = {};
  for (const [teamKey, sign] of [['blue', -1], ['orange', 1]]) {
    const team = TEAM[teamKey];
    const z = sign * FIELD.halfL;
    const goal = new THREE.Group();
    goal.position.set(0, 0, z);
    group.add(goal);

    const frameMat = new THREE.MeshStandardMaterial({
      color: team.color, emissive: team.color, emissiveIntensity: 2.4, metalness: 0.4, roughness: 0.3,
    });
    const postGeo = new THREE.CylinderGeometry(0.34, 0.42, FIELD.goalH, 10);
    for (const x of [-FIELD.goalHalfW, FIELD.goalHalfW]) {
      const post = new THREE.Mesh(postGeo, frameMat);
      post.position.set(x, FIELD.goalH / 2, 0);
      goal.add(post);
      const cap = glowSprite(team.color, 4.2, 0.7);
      cap.position.set(x, FIELD.goalH, 0.2);
      goal.add(cap);
    }
    const bar = new THREE.Mesh(new THREE.BoxGeometry(FIELD.goalHalfW * 2 + 0.7, 0.55, 0.7), frameMat);
    bar.position.set(0, FIELD.goalH, 0);
    goal.add(bar);

    // goal floor + back
    const floor = new THREE.Mesh(
      new THREE.PlaneGeometry(FIELD.goalHalfW * 2, FIELD.goalDepth),
      new THREE.MeshStandardMaterial({ color: 0x061019, roughness: 0.85, metalness: 0.2 })
    );
    floor.rotation.x = -Math.PI / 2;
    floor.position.set(0, 0.01, sign * FIELD.goalDepth / 2);
    goal.add(floor);

    const net = makeNet(team.color);
    net.position.z = sign * FIELD.goalDepth;
    if (sign > 0) net.scale.z = 1;
    const netGroup = new THREE.Group();
    netGroup.add(net);
    // side/top depth lines
    const pts = [
      -FIELD.goalHalfW, 0, 0, -FIELD.goalHalfW, 0, sign * FIELD.goalDepth,
      FIELD.goalHalfW, 0, 0, FIELD.goalHalfW, 0, sign * FIELD.goalDepth,
      -FIELD.goalHalfW, FIELD.goalH, 0, -FIELD.goalHalfW, FIELD.goalH, sign * FIELD.goalDepth,
      FIELD.goalHalfW, FIELD.goalH, 0, FIELD.goalHalfW, FIELD.goalH, sign * FIELD.goalDepth,
      -FIELD.goalHalfW, FIELD.goalH, sign * FIELD.goalDepth, FIELD.goalHalfW, FIELD.goalH, sign * FIELD.goalDepth,
    ];
    const frameGeo = new THREE.BufferGeometry();
    frameGeo.setAttribute('position', new THREE.Float32BufferAttribute(pts, 3));
    const frameLines = new THREE.LineSegments(frameGeo, new THREE.LineBasicMaterial({ color: team.color, transparent: true, opacity: 0.5 }));
    netGroup.add(frameLines);
    goal.add(netGroup);

    // back wall glow
    const backGlow = new THREE.Mesh(
      new THREE.PlaneGeometry(FIELD.goalHalfW * 2, FIELD.goalH),
      new THREE.MeshBasicMaterial({ color: team.color, transparent: true, opacity: 0.12, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide })
    );
    backGlow.position.set(0, FIELD.goalH / 2, sign * FIELD.goalDepth);
    goal.add(backGlow);
    goalGlows[teamKey] = backGlow;

    // mouth light plane
    const mouth = new THREE.Mesh(
      new THREE.PlaneGeometry(FIELD.goalHalfW * 2 - 0.6, FIELD.goalH - 0.4),
      new THREE.MeshBasicMaterial({ color: team.color, transparent: true, opacity: 0.07, blending: THREE.AdditiveBlending, depthWrite: false, side: THREE.DoubleSide })
    );
    mouth.position.set(0, FIELD.goalH / 2, -sign * 0.1);
    goal.add(mouth);

    // floor glow strip at the goal line
    const strip = new THREE.Mesh(
      new THREE.BoxGeometry(FIELD.goalHalfW * 2, 0.06, 0.6),
      new THREE.MeshBasicMaterial({ color: team.color, transparent: true, opacity: 0.9 })
    );
    strip.position.set(0, 0.04, -sign * 0.3);
    goal.add(strip);
  }

  // goal-side text screens above the mouth
  for (const [teamKey, sign] of [['blue', -1], ['orange', 1]]) {
    const team = TEAM[teamKey];
    const tex = canvasTexture(512, 128, (ctx, w, h) => {
      ctx.fillStyle = 'rgba(4,10,18,0.9)';
      ctx.fillRect(0, 0, w, h);
      ctx.strokeStyle = team.soft;
      ctx.lineWidth = 4;
      ctx.strokeRect(6, 6, w - 12, h - 12);
      ctx.fillStyle = team.soft;
      ctx.font = '900 62px Orbitron, sans-serif';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(team.name, w / 2, h / 2 + 2);
    });
    const screen = new THREE.Mesh(
      new THREE.PlaneGeometry(19, 4.6),
      new THREE.MeshBasicMaterial({ map: tex, transparent: true })
    );
    screen.position.set(0, FIELD.goalH + 3.3, sign * (FIELD.halfL + 0.2));
    screen.rotation.y = sign > 0 ? Math.PI : 0;
    group.add(screen);

    const halo = glowSprite(team.color, 26, 0.16);
    halo.position.copy(screen.position);
    group.add(halo);
  }

  // ── stands + crowd ─────────────────────────────────────────
  const standMat = new THREE.MeshStandardMaterial({ color: 0x071019, roughness: 0.9, metalness: 0.3 });
  const trimMat = new THREE.MeshBasicMaterial({ color: 0x2a7fa8, transparent: true, opacity: 0.4 });

  for (const side of [-1, 1]) {
    for (let tier = 0; tier < 3; tier++) {
      const w = 12 + tier * 6;
      const x = side * (FIELD.halfW + 9 + tier * 5);
      const step = new THREE.Mesh(new THREE.BoxGeometry(w, 2.2 + tier * 2.4, FIELD.halfL * 2 + 24), standMat);
      step.position.set(x, (2.2 + tier * 2.4) / 2, 0);
      step.receiveShadow = true;
      group.add(step);
      const trim = new THREE.Mesh(new THREE.BoxGeometry(0.2, 0.16, FIELD.halfL * 2 + 24), trimMat);
      trim.position.set(side * (FIELD.halfW + 3.2 + tier * 5), 2.2 + tier * 2.4, 0);
      group.add(trim);
    }
  }
  for (const side of [-1, 1]) {
    for (let tier = 0; tier < 3; tier++) {
      const z = side * (FIELD.halfL + 8 + tier * 5);
      const step = new THREE.Mesh(new THREE.BoxGeometry(FIELD.halfW * 2 + 42, 2.2 + tier * 2.4, 12 + tier * 5), standMat);
      step.position.set(0, (2.2 + tier * 2.4) / 2, z);
      step.receiveShadow = true;
      group.add(step);
    }
  }

  // crowd dots
  const crowdCount = 620;
  const crowd = new THREE.InstancedMesh(
    new THREE.BoxGeometry(0.42, 0.62, 0.42),
    new THREE.MeshBasicMaterial({ color: 0xffffff }),
    crowdCount
  );
  const m4 = new THREE.Matrix4();
  const c = new THREE.Color();
  const palette = [0x2fb6ff, 0x2fb6ff, 0x8bdcff, 0xff7a24, 0xff7a24, 0xffb167, 0xd8f4ff, 0x53657a];
  for (let i = 0; i < crowdCount; i++) {
    let x, y, z;
    if (i % 2 === 0) {
      const side = Math.random() < 0.5 ? -1 : 1;
      const tier = randInt(0, 2);
      x = side * (FIELD.halfW + rand(4, 21) + tier * 2);
      z = rand(-FIELD.halfL - 14, FIELD.halfL + 14);
      y = rand(2.4, 2.4 + tier * 2.4 + 2.2);
    } else {
      const side = Math.random() < 0.5 ? -1 : 1;
      const tier = randInt(0, 2);
      z = side * (FIELD.halfL + rand(5, 20) + tier * 2);
      x = rand(-FIELD.halfW - 15, FIELD.halfW + 15);
      y = rand(2.4, 2.4 + tier * 2.4 + 2.2);
    }
    m4.makeTranslation(x, y, z);
    crowd.setMatrixAt(i, m4);
    c.setHex(palette[randInt(0, palette.length - 1)]);
    c.multiplyScalar(rand(0.55, 1.1));
    crowd.setColorAt(i, c);
  }
  crowd.instanceMatrix.needsUpdate = true;
  if (crowd.instanceColor) crowd.instanceColor.needsUpdate = true;
  group.add(crowd);

  // ── overhead rig & jumbotron ───────────────────────────────
  const rigMat = new THREE.MeshStandardMaterial({ color: 0x0a1624, metalness: 0.8, roughness: 0.3 });
  for (const z of [-FIELD.halfL + 5, FIELD.halfL - 5]) {
    const truss = new THREE.Mesh(new THREE.BoxGeometry(FIELD.halfW * 2 + 12, 0.5, 0.5), rigMat);
    truss.position.set(0, 19, z);
    group.add(truss);
    for (let i = -4; i <= 4; i++) {
      const lamp = new THREE.Mesh(
        new THREE.BoxGeometry(2.4, 0.32, 0.8),
        new THREE.MeshBasicMaterial({ color: 0xdff4ff })
      );
      lamp.position.set(i * 7, 18.7, z);
      group.add(lamp);
      const glow = glowSprite(0xbfeaff, 6, 0.18);
      glow.position.copy(lamp.position);
      group.add(glow);
    }
  }

  const jumbotron = new THREE.Group();
  jumbotron.position.set(0, 23.5, 0);
  const core = new THREE.Mesh(new THREE.BoxGeometry(14, 6, 8), rigMat);
  jumbotron.add(core);
  const jumboTex = canvasTexture(512, 256, (ctx, w, h) => {
    ctx.fillStyle = '#030a12'; ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = '#55cfff'; ctx.lineWidth = 6; ctx.strokeRect(8, 8, w - 16, h - 16);
    ctx.fillStyle = '#8ce6ff';
    ctx.font = '900 52px Orbitron, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('TURBO', w / 2, 92);
    ctx.fillStyle = '#ffae62';
    ctx.fillText('STRIKERS', w / 2, 152);
    ctx.fillStyle = 'rgba(190,235,255,0.6)';
    ctx.font = '700 24px Rajdhani, sans-serif';
    ctx.fillText('NEO LEAGUE', w / 2, 204);
  });
  for (const [z, rot] of [[4.01, 0], [-4.01, Math.PI], [0, 0]]) {
    if (z === 0) continue;
    const screen = new THREE.Mesh(new THREE.PlaneGeometry(12, 4.4), new THREE.MeshBasicMaterial({ map: jumboTex }));
    screen.position.set(0, 0, z);
    screen.rotation.y = rot;
    jumbotron.add(screen);
  }
  // side screens
  const sideTex = canvasTexture(256, 160, (ctx, w, h) => {
    ctx.fillStyle = '#03111b'; ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = '#2fb6ff'; ctx.fillRect(0, 0, w, 8);
    ctx.fillStyle = '#ff7a24'; ctx.fillRect(0, h - 8, w, 8);
    ctx.fillStyle = 'rgba(200,240,255,0.7)';
    ctx.font = '900 56px Orbitron, sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('VS', w / 2, 100);
  });
  for (const [x, rot] of [[7.01, Math.PI / 2], [-7.01, -Math.PI / 2]]) {
    const screen = new THREE.Mesh(new THREE.PlaneGeometry(6.6, 4), new THREE.MeshBasicMaterial({ map: sideTex }));
    screen.position.set(x, 0, 0);
    screen.rotation.y = rot;
    jumbotron.add(screen);
  }
  // hanger cables
  for (const x of [-5, 5]) {
    const cable = new THREE.Mesh(new THREE.CylinderGeometry(0.07, 0.07, 18, 6), rigMat);
    cable.position.set(x, 8, 0);
    jumbotron.add(cable);
  }
  const jumboGlow = glowSprite(0x4fc9ff, 34, 0.13);
  jumboGlow.position.set(0, 0, 0);
  jumbotron.add(jumboGlow);
  group.add(jumbotron);

  // corner towers
  for (const sx of [-1, 1]) {
    for (const sz of [-1, 1]) {
      const tower = new THREE.Group();
      tower.position.set(sx * (FIELD.halfW + 12), 0, sz * (FIELD.halfL + 12));
      const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.4, 0.8, 21, 8), rigMat);
      mast.position.y = 10.5;
      tower.add(mast);
      const lamp = new THREE.Mesh(new THREE.BoxGeometry(4.6, 1.2, 1.1), new THREE.MeshBasicMaterial({ color: 0xe6f8ff }));
      lamp.position.y = 20.5;
      lamp.lookAt(new THREE.Vector3(0, 6, 0));
      tower.add(lamp);
      const halo = glowSprite(0xbfeaff, 11, 0.3);
      halo.position.y = 20.5;
      tower.add(halo);
      group.add(tower);
    }
  }

  scene.fog = new THREE.FogExp2(0x061018, 0.0065);

  // animated glow pulses
  const pulseMats = [goalGlows.blue.material, goalGlows.orange.material];

  return {
    group,
    goalGlows,
    stars,
    crowd,
    update(time) {
      const p = 0.5 + 0.5 * Math.sin(time * 1.6);
      goalGlows.blue.material.opacity = 0.09 + 0.06 * p;
      goalGlows.orange.material.opacity = 0.09 + 0.06 * (1 - p);
      jumbotron.rotation.y = Math.sin(time * 0.18) * 0.16;
      stars.rotation.y = time * 0.004;
    },
  };
}

import * as THREE from 'three';
import { CAR, FIELD, TEAM } from './constants.js';
import { canvasTexture, clamp, damp, glowSprite, glowTexture, rand, sparkTexture, textSprite } from './utils.js';

const _v1 = new THREE.Vector3();
const _v2 = new THREE.Vector3();

/* ═══════════════════════════════════════════════════════════
   CAR
   ═══════════════════════════════════════════════════════════ */
function buildWheel(radius, width, rimColor) {
  const pivot = new THREE.Group();
  const tireGeo = new THREE.CylinderGeometry(radius, radius, width, 16);
  tireGeo.rotateZ(Math.PI / 2);
  const tire = new THREE.Mesh(tireGeo, new THREE.MeshStandardMaterial({ color: 0x0a0d12, roughness: 0.92, metalness: 0.15 }));
  tire.castShadow = true;
  pivot.add(tire);
  const rimGeo = new THREE.CylinderGeometry(radius * 0.55, radius * 0.55, width + 0.02, 8);
  rimGeo.rotateZ(Math.PI / 2);
  const rim = new THREE.Mesh(rimGeo, new THREE.MeshStandardMaterial({ color: rimColor, metalness: 0.9, roughness: 0.25, emissive: rimColor, emissiveIntensity: 0.22 }));
  pivot.add(rim);
  return { pivot, tire };
}

export class Car {
  constructor(game, { team, name, isPlayer = false, isAI = false }) {
    this.game = game;
    this.team = team;
    this.name = name;
    this.isPlayer = isPlayer;
    this.isAI = isAI;
    this.group = new THREE.Group();
    this.group.rotation.order = 'YXZ';
    this.body = new THREE.Group();
    this.group.add(this.body);

    this.pos = this.group.position;
    this.yaw = team === 'blue' ? 0 : Math.PI;
    this.speed = 0;
    this.vel = new THREE.Vector3();
    this.vy = 0;
    this.grounded = true;
    this.jumps = 0;
    this.boost = 33;
    this.item = null;
    this.itemRolling = 0;
    this.itemCycle = 0;
    this.stun = 0;
    this.spin = 0;
    this.invincible = 0;
    this.speedTimer = 0;
    this.shrinkTimer = 0;
    this.boosting = false;
    this.boostCooldown = 0;
    this.airTime = 0;
    this.wheelSpin = 0;
    this.lastTouch = 0;
    this.aiState = { stuck: 0, reverse: 0, decision: 0, jitter: Math.random() * 10 };
    this.flamePhase = Math.random() * 10;

    this.#buildMesh();
    this.reset(0, 0, this.yaw, false);
  }

  #buildMesh() {
    const team = TEAM[this.team];
    const bodyMat = new THREE.MeshStandardMaterial({
      color: team.color, metalness: 0.62, roughness: 0.3,
      emissive: team.color, emissiveIntensity: 0.13,
    });
    const darkMat = new THREE.MeshStandardMaterial({ color: 0x0a1119, metalness: 0.7, roughness: 0.35 });
    const whiteMat = new THREE.MeshStandardMaterial({ color: 0xe8f6ff, metalness: 0.5, roughness: 0.28 });
    const glassMat = new THREE.MeshPhysicalMaterial({
      color: 0x0b2335, metalness: 0.6, roughness: 0.08, transparent: true, opacity: 0.88,
      clearcoat: 1, clearcoatRoughness: 0.1,
    });
    this.bodyMat = bodyMat;

    // chassis
    const chassis = new THREE.Mesh(new THREE.BoxGeometry(2.02, 0.5, 3.9), bodyMat);
    chassis.position.y = 0.02;
    chassis.castShadow = true;
    chassis.receiveShadow = true;
    this.body.add(chassis);

    // nose wedge
    const noseGeo = new THREE.BoxGeometry(1.72, 0.28, 1.1);
    const nose = new THREE.Mesh(noseGeo, bodyMat);
    nose.position.set(0, -0.03, 1.95);
    nose.castShadow = true;
    this.body.add(nose);
    const noseLip = new THREE.Mesh(new THREE.BoxGeometry(1.86, 0.13, 0.22), whiteMat);
    noseLip.position.set(0, -0.09, 2.48);
    this.body.add(noseLip);

    // side skirts
    for (const sx of [-1, 1]) {
      const skirt = new THREE.Mesh(new THREE.BoxGeometry(0.22, 0.24, 2.6), whiteMat);
      skirt.position.set(sx * 1.02, -0.14, 0.05);
      this.body.add(skirt);
    }

    // cabin
    const cabin = new THREE.Mesh(new THREE.BoxGeometry(1.5, 0.48, 1.62), glassMat);
    cabin.position.set(0, 0.44, -0.18);
    this.body.add(cabin);
    const roof = new THREE.Mesh(new THREE.BoxGeometry(1.24, 0.12, 1.1), bodyMat);
    roof.position.set(0, 0.7, -0.3);
    this.body.add(roof);
    const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.28, 0.05, 1.5), whiteMat);
    stripe.position.set(0, 0.77, -0.32);
    this.body.add(stripe);

    // rear spoiler
    for (const sx of [-0.62, 0.62]) {
      const support = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.42, 0.16), darkMat);
      support.position.set(sx, 0.42, -1.8);
      this.body.add(support);
    }
    const wing = new THREE.Mesh(new THREE.BoxGeometry(2.0, 0.1, 0.55), whiteMat);
    wing.position.set(0, 0.64, -1.84);
    wing.castShadow = true;
    this.body.add(wing);
    const wingTipL = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.25, 0.6), bodyMat);
    wingTipL.position.set(-1.0, 0.58, -1.84);
    this.body.add(wingTipL);
    const wingTipR = wingTipL.clone();
    wingTipR.position.x = 1.0;
    this.body.add(wingTipR);

    // lights
    const headMat = new THREE.MeshBasicMaterial({ color: 0xe6fbff });
    for (const sx of [-0.63, 0.63]) {
      const head = new THREE.Mesh(new THREE.BoxGeometry(0.4, 0.12, 0.06), headMat);
      head.position.set(sx, 0.06, 2.505);
      this.body.add(head);
    }
    const tailMat = new THREE.MeshBasicMaterial({ color: 0xff3b25 });
    for (const sx of [-0.62, 0.62]) {
      const tail = new THREE.Mesh(new THREE.BoxGeometry(0.38, 0.12, 0.06), tailMat);
      tail.position.set(sx, 0.14, -1.99);
      this.body.add(tail);
    }

    // wheels
    this.wheels = [];
    const wheelPositions = [
      [-0.98, -0.3, 1.32, true],
      [0.98, -0.3, 1.32, true],
      [-0.98, -0.3, -1.32, false],
      [0.98, -0.3, -1.32, false],
    ];
    for (const [x, y, z, front] of wheelPositions) {
      const { pivot, tire } = buildWheel(0.38, 0.34, 0xbcd8e8);
      pivot.position.set(x, y, z);
      this.body.add(pivot);
      this.wheels.push({ pivot, tire, front, baseY: y });
    }

    // boost flames
    this.flames = [];
    const flameMat = new THREE.MeshBasicMaterial({
      color: 0xffb347, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false,
    });
    for (const sx of [-0.5, 0.5]) {
      const flame = new THREE.Mesh(new THREE.ConeGeometry(0.2, 1.0, 8), flameMat.clone());
      flame.rotation.x = -Math.PI / 2;
      flame.position.set(sx, 0.0, -2.2);
      flame.visible = false;
      this.body.add(flame);
      this.flames.push(flame);
    }

    // underglow
    const glow = new THREE.Mesh(
      new THREE.PlaneGeometry(3.8, 5.4),
      new THREE.MeshBasicMaterial({
        map: glowTexture(), color: team.color, transparent: true, opacity: 0.4,
        blending: THREE.AdditiveBlending, depthWrite: false,
      })
    );
    glow.rotation.x = -Math.PI / 2;
    glow.position.y = -0.72;
    this.body.add(glow);
    this.underglow = glow;

    // shield bubble (star)
    this.bubble = new THREE.Mesh(
      new THREE.IcosahedronGeometry(2.55, 2),
      new THREE.MeshBasicMaterial({
        color: 0xffe37a, transparent: true, opacity: 0.28, wireframe: true,
        blending: THREE.AdditiveBlending, depthWrite: false,
      })
    );
    this.bubble.position.y = 0.1;
    this.bubble.visible = false;
    this.body.add(this.bubble);

    // stun stars
    this.stunGroup = new THREE.Group();
    this.stunGroup.position.set(0, 2.3, 0);
    const starMat = new THREE.MeshBasicMaterial({ color: 0xffdf6a });
    for (let i = 0; i < 3; i++) {
      const star = new THREE.Mesh(new THREE.OctahedronGeometry(0.17, 0), starMat);
      this.stunGroup.add(star);
    }
    this.stunGroup.visible = false;
    this.group.add(this.stunGroup);

    // nameplate
    const sprite = textSprite(this.name, team.soft, 'rgba(3,10,18,0.62)');
    sprite.position.set(0, 3.35, 0);
    sprite.scale.set(5.4, 1.35, 1);
    this.group.add(sprite);
    this.nameplate = sprite;

    this.group.traverse((o) => {
      if (o.isMesh && o !== this.bubble && o !== this.underglow) o.castShadow = true;
    });
  }

  reset(x, z, yaw = this.yaw, full = true) {
    this.pos.set(x, CAR.groundY, z);
    this.yaw = yaw;
    this.speed = 0;
    this.vy = 0;
    this.vel.set(0, 0, 0);
    this.grounded = true;
    this.jumps = 0;
    this.stun = 0;
    this.spin = 0;
    this.invincible = 0;
    this.speedTimer = 0;
    this.shrinkTimer = 0;
    this.itemRolling = 0;
    this.boosting = false;
    this.airTime = 0;
    this.body.rotation.set(0, 0, 0);
    this.body.scale.setScalar(1);
    if (full) {
      this.boost = 33;
      this.item = null;
      this.itemCycle = 0;
    }
    this.group.rotation.y = yaw;
    this.syncVisual(0);
  }

  get forward() {
    return _v1.set(Math.sin(this.yaw), 0, Math.cos(this.yaw));
  }

  get right() {
    return _v2.set(Math.cos(this.yaw), 0, -Math.sin(this.yaw));
  }

  get speedNorm() {
    return clamp(Math.abs(this.speed) / CAR.boostMax, 0, 1);
  }

  hasItem() {
    return this.item && this.itemRolling <= 0;
  }

  giveItem(item) {
    this.item = item;
    this.itemRolling = this.isPlayer ? 0.9 : 0;
    this.itemCycle = 0;
  }

  stunCar(duration = 1.1, spinDir = 1) {
    if (this.invincible > 0) return false;
    if (this.stun <= 0) {
      this.spin = rand(9, 14) * spinDir;
      this.speed *= 0.26;
      this.vy = Math.max(this.vy, 4);
      this.grounded = false;
    }
    this.stun = Math.max(this.stun, duration);
    return true;
  }

  update(ctrl, dt, game) {
    const c = ctrl || {};
    const throttle = this.stun > 0 ? 0 : clamp(c.throttle || 0, -1, 1);
    const steer = this.stun > 0 ? 0 : clamp(c.steer || 0, -1, 1);

    // timers
    this.stun = Math.max(0, this.stun - dt);
    this.invincible = Math.max(0, this.invincible - dt);
    this.speedTimer = Math.max(0, this.speedTimer - dt);
    this.shrinkTimer = Math.max(0, this.shrinkTimer - dt);
    this.itemRolling = Math.max(0, this.itemRolling - dt);
    this.boostCooldown = Math.max(0, this.boostCooldown - dt);
    this.lastTouch = Math.max(0, this.lastTouch - dt);

    if (this.itemRolling > 0) {
      this.itemCycle -= dt;
      if (this.itemCycle <= 0) {
        this.itemCycle = 0.075;
        game.sound.rouletteTick();
        game.ui.flashRoulette();
      }
    }

    const superCharge = this.speedTimer > 0 ? 1 : 0;
    const boosting = !!c.boost && this.boost > 0.5 && this.stun <= 0;
    this.boosting = boosting;

    if (boosting) {
      this.boost = Math.max(0, this.boost - 34 * dt);
      if (this.boostCooldown <= 0) {
        this.boostCooldown = 0.35;
        game.sound.boostStart();
      }
    }

    const fwd = this.forward.clone();
    const right = this.right.clone();
    const maxSpeed = (boosting ? CAR.boostMax : CAR.maxSpeed) * (superCharge ? 1.32 : 1);

    if (this.grounded) {
      if (throttle > 0.05) {
        this.speed += CAR.accel * throttle * dt * (superCharge ? 1.5 : 1);
      } else if (throttle < -0.05) {
        if (this.speed > 0.6) this.speed -= 66 * dt;
        else this.speed += 20 * throttle * dt;
      } else {
        this.speed -= this.speed * 2.4 * dt;
      }
      if (boosting) this.speed += CAR.boostAccel * dt * (superCharge ? 1.35 : 1);
      this.speed = clamp(this.speed, -CAR.reverseMax, maxSpeed);

      const steerAuthority = Math.min(1, Math.abs(this.speed) / 6) * (1 - 0.22 * Math.min(1, Math.abs(this.speed) / maxSpeed));
      this.yaw += steer * CAR.turnRate * dt * steerAuthority * (this.speed < -0.2 ? -1 : 1);

      this.vel.set(Math.sin(this.yaw) * this.speed, 0, Math.cos(this.yaw) * this.speed);
      this.pos.x += this.vel.x * dt;
      this.pos.z += this.vel.z * dt;

      if (c.jump && this.jumps === 0) {
        this.grounded = false;
        this.vy = CAR.jumpSpeed;
        this.jumps = 1;
        this.pos.y += this.vy * dt;
        game.sound.jump();
        game.particles.spawnBurst(_v1.set(this.pos.x, this.pos.y - 0.4, this.pos.z), TEAM[this.team].color, 8, 4, 0.35, 8, 0.5);
      } else {
        this.pos.y = CAR.groundY;
        this.vy = 0;
      }

      // drifting sparks
      if (Math.abs(steer) > 0.7 && Math.abs(this.speed) > 18 && Math.random() < 0.4) {
        game.particles.spawnBurst(
          new THREE.Vector3(this.pos.x - fwd.x * 1.6, 0.25, this.pos.z - fwd.z * 1.6),
          TEAM[this.team].color, 1, 2.5, 0.22, 9, 0.35
        );
      }
    } else {
      this.airTime += dt;
      this.yaw += steer * 1.4 * dt;
      if (throttle !== 0) {
        this.vel.x += fwd.x * throttle * 10 * dt;
        this.vel.z += fwd.z * throttle * 10 * dt;
      }
      if (boosting) {
        this.vel.x += fwd.x * 24 * dt;
        this.vel.z += fwd.z * 24 * dt;
        this.vy += 25 * dt;
        game.particles.spawnBoost(this);
      }
      if (c.jump && this.jumps < 2 && this.stun <= 0) {
        this.jumps = 2;
        this.vy = Math.max(this.vy, 4.5) + 4.4;
        this.vel.x += fwd.x * 6 + right.x * steer * 6;
        this.vel.z += fwd.z * 6 + right.z * steer * 6;
        this.spin += steer * 4;
        game.sound.flip();
        game.particles.spawnBurst(new THREE.Vector3(this.pos.x, this.pos.y - 0.3, this.pos.z), 0xbdeaff, 10, 5, 0.3, 4, 0.45);
      }
      this.vy -= CAR.gravity * dt;
      this.pos.x += this.vel.x * dt;
      this.pos.z += this.vel.z * dt;
      this.pos.y += this.vy * dt;

      if (this.pos.y <= CAR.groundY) {
        this.pos.y = CAR.groundY;
        this.vy = 0;
        this.grounded = true;
        this.jumps = 0;
        this.speed = clamp(this.vel.x * fwd.x + this.vel.z * fwd.z, -CAR.reverseMax, CAR.boostMax);
        this.airTime = 0;
        if (this.vel.length() > 16) {
          game.particles.spawnBurst(new THREE.Vector3(this.pos.x, 0.2, this.pos.z), 0xbfd9e8, 8, 4, 0.32, 10, 0.45);
        }
      }
    }

    // world bounds for cars
    const bx = FIELD.halfW - 1.25;
    const bz = FIELD.halfL - 1.25;
    if (this.pos.x < -bx) { this.pos.x = -bx; this.speed *= 0.5; this.vel.x *= -0.2; }
    if (this.pos.x > bx) { this.pos.x = bx; this.speed *= 0.5; this.vel.x *= -0.2; }
    if (this.pos.z < -bz) { this.pos.z = -bz; this.speed *= 0.5; this.vel.z *= -0.2; }
    if (this.pos.z > bz) { this.pos.z = bz; this.speed *= 0.5; this.vel.z *= -0.2; }

    // stun spin
    if (this.stun > 0) {
      this.spin = damp(this.spin, 0, 2.4, dt);
      this.body.rotation.y += this.spin * dt;
      this.body.rotation.z = damp(this.body.rotation.z, Math.sin(this.stun * 18) * 0.16, 5, dt);
    } else {
      this.body.rotation.y = damp(this.body.rotation.y, 0, 8, dt);
      this.body.rotation.z = damp(this.body.rotation.z, -steer * 0.075 * Math.min(1, Math.abs(this.speed) / 20), 9, dt);
      this.body.rotation.x = damp(this.body.rotation.x, this.grounded ? 0 : clamp(-this.vy * 0.012, -0.12, 0.14), 6, dt);
    }

    // boost flames
    const flameScale = boosting ? rand(0.85, 1.35) : 0;
    this.flamePhase += dt * 24;
    for (const f of this.flames) {
      f.visible = boosting;
      if (boosting) {
        f.scale.set(0.8 + Math.sin(this.flamePhase) * 0.18, flameScale, 0.8 + Math.cos(this.flamePhase * 0.7) * 0.18);
        f.material.color.setHex(this.speedTimer > 0 ? 0xff6a9e : 0xffb347);
      }
    }
    if (boosting) {
      const p = this.pos.clone().addScaledVector(fwd, -2.3);
      game.particles.spawnBoost(this);
    }

    // wheel animation
    this.wheelSpin += this.speed * dt / 0.38;
    for (const w of this.wheels) {
      w.tire.rotation.x = this.wheelSpin;
      if (w.front) w.pivot.rotation.y = damp(w.pivot.rotation.y, steer * 0.42, 12, dt);
    }

    // shield / star visuals
    const star = this.invincible > 0;
    this.bubble.visible = star;
    if (star) {
      this.bubble.rotation.y += dt * 2;
      this.bubble.rotation.x += dt * 0.7;
      const hue = (game.time * 0.55) % 1;
      this.bubble.material.color.setHSL(hue, 0.9, 0.65);
      this.bodyMat.emissive.setHSL(hue, 0.85, 0.3);
      this.bodyMat.emissiveIntensity = 0.75 + Math.sin(game.time * 12) * 0.2;
      if (Math.random() < 0.5) {
        game.particles.spawnBurst(new THREE.Vector3(this.pos.x + rand(-1.4, 1.4), this.pos.y + rand(-0.3, 1.4), this.pos.z + rand(-1.8, 1.8)), new THREE.Color().setHSL(Math.random(), 0.9, 0.65), 1, 1.4, 0.3, -1, 0.55);
      }
    } else {
      this.bodyMat.emissive.setHex(TEAM[this.team].color);
      this.bodyMat.emissiveIntensity = 0.13;
    }

    // speed item aura
    if (this.speedTimer > 0) {
      this.underglow.material.opacity = 0.55 + Math.sin(game.time * 14) * 0.15;
      this.underglow.material.color.setHex(0xffd36a);
    } else {
      this.underglow.material.opacity = 0.32;
      this.underglow.material.color.setHex(TEAM[this.team].color);
    }

    // shrink
    const targetScale = this.shrinkTimer > 0 ? 0.56 : 1;
    const s = damp(this.body.scale.x, targetScale, 8, dt);
    this.body.scale.setScalar(s);

    // stun stars
    this.stunGroup.visible = this.stun > 0;
    if (this.stun > 0) {
      this.stunGroup.rotation.y += dt * 8;
      [...this.stunGroup.children].forEach((starMesh, i) => {
        const a = game.time * 7 + (i / 3) * Math.PI * 2;
        starMesh.position.set(Math.cos(a) * 0.9, Math.sin(a * 2) * 0.12, Math.sin(a) * 0.9);
      });
    }

    this.syncVisual(dt);
  }

  syncVisual(dt) {
    this.group.rotation.y = this.yaw;
  }

  // collider helpers
  getCollider() {
    return { pos: this.pos, yaw: this.yaw, halfW: CAR.halfW, halfH: CAR.halfH, halfL: CAR.halfL };
  }
}

/* ═══════════════════════════════════════════════════════════
   BALL
   ═══════════════════════════════════════════════════════════ */
function ballTexture() {
  return canvasTexture(1024, 1024, (ctx, w, h) => {
    ctx.fillStyle = '#dcecf4';
    ctx.fillRect(0, 0, w, h);
    const R = 62;
    const dx = R * 1.75;
    const dy = R * 1.5;
    for (let row = -1; row < h / dy + 2; row++) {
      for (let col = -1; col < w / dx + 2; col++) {
        const x = col * dx + (row % 2 ? dx / 2 : 0);
        const y = row * dy;
        const spots = [
          [x, y, R * 0.92],
          [x + dx / 2, y + dy / 2, R * 0.92],
        ];
        for (const [cx, cy, cr] of spots) {
          ctx.beginPath();
          for (let i = 0; i < 6; i++) {
            const a = (i / 6) * Math.PI * 2;
            const px = cx + Math.cos(a) * cr;
            const py = cy + Math.sin(a) * cr;
            if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py);
          }
          ctx.closePath();
          ctx.fillStyle = (row + col) % 2 === 0 ? '#c9deea' : '#eefaff';
          ctx.fill();
          ctx.strokeStyle = 'rgba(30, 56, 74, 0.55)';
          ctx.lineWidth = 4;
          ctx.stroke();
        }
      }
    }
    // subtle scuffs
    ctx.globalAlpha = 0.08;
    for (let i = 0; i < 90; i++) {
      ctx.fillStyle = '#3a5b70';
      ctx.beginPath();
      ctx.arc(Math.random() * w, Math.random() * h, Math.random() * 20 + 2, 0, Math.PI * 2);
      ctx.fill();
    }
  }, { anisotropy: 8 });
}

export class Ball {
  constructor(game) {
    this.game = game;
    this.group = new THREE.Group();
    this.pos = this.group.position;
    this.vel = new THREE.Vector3();
    this.radius = FIELD.ballRadius;
    this.lastTouchTeam = null;
    this.lastTouchCar = null;
    this.spinAxis = new THREE.Vector3(1, 0, 0);
    this.spinSpeed = 0;

    const mesh = new THREE.Mesh(
      new THREE.SphereGeometry(FIELD.ballRadius, 36, 26),
      new THREE.MeshPhysicalMaterial({
        map: ballTexture(), roughness: 0.38, metalness: 0.18, clearcoat: 0.6, clearcoatRoughness: 0.25,
        emissive: 0x1a3a4a, emissiveIntensity: 0.22,
      })
    );
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    this.mesh = mesh;
    this.group.add(mesh);

    const aura = glowSprite(0x9be8ff, 8.6, 0.16);
    this.group.add(aura);

    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(FIELD.ballRadius * 1.08, 0.045, 6, 48),
      new THREE.MeshBasicMaterial({ color: 0x8fe7ff, transparent: true, opacity: 0.35, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    ring.rotation.x = Math.PI / 2;
    this.group.add(ring);
    this.ring = ring;

    // trail
    this.trailLength = 26;
    this.trailPoints = [];
    for (let i = 0; i < this.trailLength; i++) this.trailPoints.push(new THREE.Vector3());
    const trailGeo = new THREE.BufferGeometry().setFromPoints(this.trailPoints);
    this.trail = new THREE.Line(trailGeo, new THREE.LineBasicMaterial({
      color: 0x9be8ff, transparent: true, opacity: 0.28, blending: THREE.AdditiveBlending, depthWrite: false,
    }));
    this.trail.frustumCulled = false;
    game.scene.add(this.trail);
    this.trailInited = false;
  }

  reset(x = 0, y = FIELD.ballRadius + 4, z = 0) {
    this.pos.set(x, y, z);
    this.vel.set(0, 0, 0);
    this.lastTouchTeam = null;
    this.lastTouchCar = null;
    this.spinSpeed = 0;
    this.trailInited = false;
    this.mesh.rotation.set(0, 0, 0);
    this.group.visible = true;
  }

  setPosition(x, y, z) {
    this.pos.set(x, y, z);
  }

  kick(impulse) {
    this.vel.add(impulse);
    if (this.vel.length() > 74) this.vel.setLength(74);
  }

  update(dt) {
    this.vel.y -= 31 * dt;
    this.pos.addScaledVector(this.vel, dt);

    // ground
    if (this.pos.y < this.radius) {
      this.pos.y = this.radius;
      if (this.vel.y < 0) {
        const impact = -this.vel.y;
        this.vel.y = impact * 0.72;
        if (impact > 3) {
          this.game.sound.hit(Math.min(1, impact / 25) * 0.4);
          this.game.particles.spawnBurst(new THREE.Vector3(this.pos.x, 0.3, this.pos.z), 0xcfeaff, 6, 3, 0.35, 6, 0.4);
        }
        if (Math.abs(this.vel.y) < 1.4) this.vel.y = 0;
      }
      this.vel.x *= 0.995;
      this.vel.z *= 0.995;
    }

    // side walls
    if (Math.abs(this.pos.x) > FIELD.halfW - this.radius) {
      this.pos.x = Math.sign(this.pos.x) * (FIELD.halfW - this.radius);
      this.vel.x *= -0.78;
      this.game.sound.wall();
      this.game.particles.spawnBurst(new THREE.Vector3(this.pos.x, this.pos.y, this.pos.z), 0x9be8ff, 5, 3, 0.3, 5, 0.35);
    }

    // ceiling
    if (this.pos.y > FIELD.ceiling) {
      this.pos.y = FIELD.ceiling;
      this.vel.y *= -0.6;
    }

    // end walls / goal mouths
    const goalMouth = Math.abs(this.pos.x) < FIELD.goalHalfW - 0.15 && this.pos.y < FIELD.goalH - 0.15;
    if (this.pos.z > FIELD.halfL - this.radius && !goalMouth) {
      this.pos.z = FIELD.halfL - this.radius;
      this.vel.z *= -0.8;
      this.game.sound.wall();
    } else if (this.pos.z < -FIELD.halfL + this.radius && !goalMouth) {
      this.pos.z = -FIELD.halfL + this.radius;
      this.vel.z *= -0.8;
      this.game.sound.wall();
    }

    // rolling spin
    const speed = this.vel.length();
    if (speed > 0.2) {
      this.spinAxis.set(this.vel.z, 0, -this.vel.x).normalize();
      this.spinSpeed = speed / this.radius;
      this.mesh.rotateOnWorldAxis(this.spinAxis, this.spinSpeed * dt * 0.6);
      this.ring.rotation.z += dt * 0.6;
    }
    this.ring.material.opacity = 0.18 + Math.min(0.5, speed / 70) * 0.5;
    this.ring.scale.setScalar(1 + Math.sin(this.game.time * 3) * 0.02);

    // trail
    const t = this.trailPoints;
    if (!this.trailInited) {
      for (const p of t) p.copy(this.pos);
      this.trailInited = true;
    }
    for (let i = t.length - 1; i > 0; i--) t[i].copy(t[i - 1]);
    t[0].copy(this.pos);
    this.trail.geometry.setFromPoints(t);
    this.trail.material.opacity = clamp((speed - 7) / 60, 0, 1) * 0.4;
  }

  // Sphere vs car OBB. Returns hit normal world or null.
  collideCar(car) {
    const dx = this.pos.x - car.pos.x;
    const dy = this.pos.y - car.pos.y;
    const dz = this.pos.z - car.pos.z;
    const cos = Math.cos(car.yaw);
    const sin = Math.sin(car.yaw);
    const lx = cos * dx - sin * dz;
    const lz = sin * dx + cos * dz;
    const ly = dy;
    const cx = clamp(lx, -CAR.halfW, CAR.halfW);
    const cy = clamp(ly, -CAR.halfH, CAR.halfH);
    const cz = clamp(lz, -CAR.halfL, CAR.halfL);
    const nx = lx - cx;
    const ny = ly - cy;
    const nz = lz - cz;
    const distSq = nx * nx + ny * ny + nz * nz;
    if (distSq > this.radius * this.radius) return null;

    let dist = Math.sqrt(distSq);
    let nlx, nly, nlz;
    if (dist < 0.0001) {
      // ball center inside box: push out along nearest face
      const px = CAR.halfW - Math.abs(lx);
      const py = CAR.halfH - Math.abs(ly);
      const pz = CAR.halfL - Math.abs(lz);
      if (px < py && px < pz) { nlx = Math.sign(lx) || 1; nly = 0; nlz = 0; dist = 0; }
      else if (py < pz) { nlx = 0; nly = Math.sign(ly) || 1; nlz = 0; dist = 0; }
      else { nlx = 0; nly = 0; nlz = Math.sign(lz) || 1; dist = 0; }
    } else {
      nlx = nx / dist; nly = ny / dist; nlz = nz / dist;
    }
    // local normal -> world
    const wx = cos * nlx + sin * nlz;
    const wz = -sin * nlx + cos * nlz;
    const wy = nly;

    const penetration = this.radius - dist;
    this.pos.x += wx * penetration;
    this.pos.y += wy * penetration;
    this.pos.z += wz * penetration;

    const normal = new THREE.Vector3(wx, wy, wz);
    const carVel = new THREE.Vector3(car.vel.x, car.vy, car.vel.z);
    const rel = this.vel.clone().sub(carVel);
    const relDot = rel.dot(normal);
    if (relDot < 0) {
      this.vel.sub(normal.clone().multiplyScalar(relDot * 1.35));
    }

    const hitStrength = Math.max(0, -relDot) + Math.abs(car.speed) * 0.32 + (car.boosting ? 6 : 0);
    const impulse = normal.clone().multiplyScalar(4.5 + hitStrength * 0.85);
    impulse.addScaledVector(new THREE.Vector3(car.vel.x, 0, car.vel.z), 0.42);
    impulse.y += 2.4 + Math.min(6, hitStrength * 0.22);
    this.kick(impulse);
    this.lastTouchTeam = car.team;
    this.lastTouchCar = car;
    car.lastTouch = 1.2;

    const power = clamp(hitStrength / 34, 0.15, 1);
    this.game.sound.hit(power);
    this.game.cameraShake = Math.max(this.game.cameraShake, power * 0.35);
    this.game.particles.spawnBurst(new THREE.Vector3(this.pos.x, this.pos.y, this.pos.z), 0xcdefff, Math.round(5 + power * 12), 5 + power * 8, 0.4, 3, 0.45);
    return normal;
  }
}

/* ═══════════════════════════════════════════════════════════
   ITEM BOX
   ═══════════════════════════════════════════════════════════ */
function questionTexture() {
  return canvasTexture(256, 256, (ctx, w, h) => {
    const g = ctx.createLinearGradient(0, 0, w, h);
    g.addColorStop(0, '#24c7ff');
    g.addColorStop(0.45, '#5b7bff');
    g.addColorStop(1, '#ff4fa8');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, w, h);
    ctx.strokeStyle = 'rgba(255,255,255,0.45)';
    ctx.lineWidth = 10;
    ctx.strokeRect(8, 8, w - 16, h - 16);
    ctx.fillStyle = 'rgba(255,255,255,0.92)';
    ctx.font = '900 170px Orbitron, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.shadowColor = 'rgba(0,30,60,0.55)';
    ctx.shadowBlur = 22;
    ctx.fillText('?', w / 2, h / 2 + 10);
  });
}

export class ItemBox {
  constructor(game, x, z) {
    this.game = game;
    this.home = new THREE.Vector3(x, 2.35, z);
    this.group = new THREE.Group();
    this.group.position.copy(this.home);
    this.active = true;
    this.respawn = 0;
    this.phase = Math.random() * Math.PI * 2;

    const tex = questionTexture();
    const cube = new THREE.Mesh(
      new THREE.BoxGeometry(2.3, 2.3, 2.3),
      new THREE.MeshStandardMaterial({
        map: tex, emissiveMap: tex, emissive: 0xffffff, emissiveIntensity: 0.7,
        metalness: 0.45, roughness: 0.28, transparent: true, opacity: 0.96,
      })
    );
    cube.castShadow = true;
    this.cube = cube;
    this.group.add(cube);

    const edges = new THREE.LineSegments(
      new THREE.EdgesGeometry(new THREE.BoxGeometry(2.42, 2.42, 2.42)),
      new THREE.LineBasicMaterial({ color: 0xd7f4ff, transparent: true, opacity: 0.65 })
    );
    this.group.add(edges);

    const glow = glowSprite(0x8fe4ff, 5.2, 0.35);
    this.group.add(glow);
    this.glow = glow;
    this.group.position.y = this.home.y;
  }

  update(dt, time) {
    if (!this.active) {
      this.respawn -= dt;
      if (this.respawn <= 0) {
        this.active = true;
        this.group.visible = true;
      }
      return;
    }
    this.group.rotation.y += dt * 0.85;
    this.group.rotation.x = Math.sin(time * 1.2 + this.phase) * 0.16;
    this.group.position.y = this.home.y + Math.sin(time * 1.8 + this.phase) * 0.25;
    const s = 1 + Math.sin(time * 3 + this.phase) * 0.035;
    this.group.scale.setScalar(s);
    this.glow.material.opacity = 0.25 + Math.sin(time * 4 + this.phase) * 0.1;
  }

  collect() {
    if (!this.active) return false;
    this.active = false;
    this.group.visible = false;
    this.respawn = 4.5;
    this.game.particles.spawnBurst(this.group.position.clone(), 0xaeecff, 18, 6, 0.4, -1, 0.65);
    this.game.sound.pickup();
    return true;
  }
}

/* ═══════════════════════════════════════════════════════════
   BOOST PAD
   ═══════════════════════════════════════════════════════════ */
export class BoostPad {
  constructor(game, x, z, big) {
    this.game = game;
    this.x = x;
    this.z = z;
    this.big = big;
    this.amount = big ? 100 : 25;
    this.active = true;
    this.respawn = 0;
    this.group = new THREE.Group();
    this.group.position.set(x, 0.05, z);

    const radius = big ? 2.05 : 1.1;
    const base = new THREE.Mesh(
      new THREE.CylinderGeometry(radius, radius, 0.1, 6),
      new THREE.MeshStandardMaterial({
        color: 0xffb020, emissive: 0xffa000, emissiveIntensity: big ? 1.2 : 0.8,
        metalness: 0.55, roughness: 0.3, transparent: true, opacity: 0.9,
      })
    );
    base.rotation.y = Math.PI / 6;
    this.group.add(base);
    this.base = base;

    const ring = new THREE.Mesh(
      new THREE.TorusGeometry(radius * 1.05, big ? 0.09 : 0.06, 6, 24),
      new THREE.MeshBasicMaterial({ color: 0xffe09a, transparent: true, opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    ring.rotation.x = -Math.PI / 2;
    this.group.add(ring);
    this.ring = ring;

    const glow = glowSprite(0xffc95e, big ? 7 : 4.4, 0.4);
    glow.position.y = 0.2;
    this.group.add(glow);
    this.glow = glow;
    this.phase = Math.random() * 10;
    game.scene.add(this.group);
  }

  update(dt) {
    if (!this.active) {
      this.respawn -= dt;
      if (this.respawn <= 0) {
        this.active = true;
        this.group.visible = true;
      }
      return;
    }
    this.ring.rotation.z += dt * 1.7;
    this.ring.scale.setScalar(1 + Math.sin(this.game.time * 4 + this.phase) * 0.06);
    this.glow.material.opacity = 0.3 + Math.sin(this.game.time * 5 + this.phase) * 0.14;
  }

  tryCollect(car) {
    if (!this.active || !car.grounded) return false;
    const dx = car.pos.x - this.x;
    const dz = car.pos.z - this.z;
    const r = this.big ? 2.9 : 2.0;
    if (dx * dx + dz * dz > r * r) return false;
    if (car.boost >= 99.5) return false;
    car.boost = Math.min(100, car.boost + this.amount);
    this.active = false;
    this.group.visible = false;
    this.respawn = this.big ? 9 : 5;
    this.game.particles.spawnBurst(new THREE.Vector3(this.x, 0.4, this.z), 0xffcc62, this.big ? 16 : 7, 5, 0.35, 5, 0.55);
    if (car.isPlayer) this.game.sound.pickup();
    return true;
  }
}

/* ═══════════════════════════════════════════════════════════
   PROJECTILES
   ═══════════════════════════════════════════════════════════ */
export class Projectile {
  constructor(game, type, pos, vel, owner) {
    this.game = game;
    this.type = type;
    this.pos = pos.clone();
    this.vel = vel.clone();
    this.owner = owner;
    this.life = type === 'red' ? 7.5 : 6.5;
    this.radius = type === 'bobomb' ? 0.9 : 0.78;
    this.fuse = type === 'bobomb' ? 1.9 : 0;
    this.target = null;
    this.dead = false;
    this.group = new THREE.Group();
    this.group.position.copy(this.pos);
    this.spin = rand(4, 9);

    if (type === 'green' || type === 'red') {
      const mainColor = type === 'green' ? 0x35d45c : 0xff3d3d;
      const shell = new THREE.Mesh(
        new THREE.SphereGeometry(0.78, 18, 14),
        new THREE.MeshStandardMaterial({ color: mainColor, metalness: 0.4, roughness: 0.25, emissive: mainColor, emissiveIntensity: 0.5 })
      );
      shell.castShadow = true;
      this.group.add(shell);
      const band = new THREE.Mesh(
        new THREE.TorusGeometry(0.62, 0.17, 7, 20),
        new THREE.MeshStandardMaterial({ color: 0xf2f8e8, roughness: 0.5 })
      );
      band.rotation.x = Math.PI / 2;
      this.group.add(band);
      const glow = glowSprite(mainColor, 3.6, 0.5);
      this.group.add(glow);
      this.mesh = shell;
    } else if (type === 'banana') {
      this.life = 24;
      const mat = new THREE.MeshStandardMaterial({ color: 0xffd83a, metalness: 0.05, roughness: 0.55, emissive: 0x8a6a00, emissiveIntensity: 0.25 });
      const arc = new THREE.Mesh(new THREE.TorusGeometry(0.58, 0.2, 8, 16, Math.PI * 1.15), mat);
      arc.rotation.z = Math.PI * 0.42;
      arc.rotation.y = Math.PI / 2;
      arc.castShadow = true;
      this.group.add(arc);
      for (const [x, y, z] of [[0.15, 0.64, 0], [0.15, -0.64, 0]]) {
        const tip = new THREE.Mesh(new THREE.SphereGeometry(0.14, 8, 6), new THREE.MeshStandardMaterial({ color: 0x6b4a1c, roughness: 0.8 }));
        tip.position.set(0, y, z);
        this.group.add(tip);
      }
      const glow = glowSprite(0xffd23f, 3, 0.3);
      this.group.add(glow);
      this.mesh = arc;
    } else {
      // bob-omb
      const body = new THREE.Mesh(
        new THREE.SphereGeometry(0.85, 18, 14),
        new THREE.MeshStandardMaterial({ color: 0x141821, metalness: 0.45, roughness: 0.35, emissive: 0x11151d, emissiveIntensity: 0.5 })
      );
      body.castShadow = true;
      this.group.add(body);
      const cap = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.3, 0.25, 8), new THREE.MeshStandardMaterial({ color: 0xc8d2dd, metalness: 0.8, roughness: 0.3 }));
      cap.position.y = 0.86;
      this.group.add(cap);
      const fuse = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.04, 0.55, 5), new THREE.MeshStandardMaterial({ color: 0x7c6242 }));
      fuse.position.y = 1.2;
      fuse.rotation.z = 0.3;
      this.group.add(fuse);
      this.spark = glowSprite(0xffb347, 1.8, 0.9);
      this.spark.position.set(0.1, 1.5, 0);
      this.group.add(this.spark);
      this.mesh = body;
    }
    game.scene.add(this.group);
  }

  update(dt, game) {
    this.life -= dt;
    if (this.life <= 0) { this.die(); return; }

    if (this.type === 'banana') {
      this.group.rotation.y += dt * 1.4;
      const bob = Math.sin(game.time * 3 + this.pos.x) * 0.04;
      this.group.position.copy(this.pos);
      this.group.position.y = this.pos.y + bob;
      return;
    }

    if (this.type === 'red' && this.target && !this.target.dead) {
      const toTarget = this.target.pos.clone().sub(this.pos);
      toTarget.y *= 0.25;
      const dist = toTarget.length();
      const desired = toTarget.normalize().multiplyScalar(46);
      this.vel.lerp(desired, clamp(4.2 * dt, 0, 1));
      if (dist < 4) this.die(true);
    }

    if (this.type === 'bobomb') {
      this.vel.y -= 27 * dt;
      this.fuse -= dt;
      if (this.pos.y < 0.9) {
        this.pos.y = 0.9;
        this.vel.y *= -0.45;
        this.vel.x *= 0.8;
        this.vel.z *= 0.8;
      }
      if (this.fuse <= 0) {
        game.explodeBobomb(this.pos.clone(), this.owner);
        this.die();
        return;
      }
      this.spark.scale.setScalar(1.3 + Math.sin(game.time * 30) * 0.4);
    }

    this.pos.addScaledVector(this.vel, dt);
    this.group.position.copy(this.pos);
    this.group.rotation.x += this.spin * dt;
    this.group.rotation.z += this.spin * 0.7 * dt;

    // walls (not banana)
    const r = this.radius;
    if (Math.abs(this.pos.x) > FIELD.halfW - r) {
      this.pos.x = Math.sign(this.pos.x) * (FIELD.halfW - r);
      this.vel.x *= -0.9;
      game.sound.wall();
    }
    if (this.type !== 'bobomb') {
      if (this.pos.z > FIELD.halfL - r) {
        this.pos.z = FIELD.halfL - r;
        this.vel.z *= -0.9;
      } else if (this.pos.z < -FIELD.halfL + r) {
        this.pos.z = -FIELD.halfL + r;
        this.vel.z *= -0.9;
      }
      this.pos.y = Math.max(1.1, this.pos.y);
    }
  }

  die(explode = false) {
    if (this.dead) return;
    this.dead = true;
    this.game.scene.remove(this.group);
    const color = this.type === 'green' ? 0x45e06b : this.type === 'red' ? 0xff4444 : this.type === 'banana' ? 0xffd23f : 0xff8a3d;
    this.game.particles.spawnBurst(this.pos.clone(), color, explode ? 16 : 8, 5, 0.35, 8, 0.45);
    if (explode) this.game.sound.explosion();
  }
}

/* ═══════════════════════════════════════════════════════════
   PARTICLES
   ═══════════════════════════════════════════════════════════ */
export class Particles {
  constructor(game) {
    this.game = game;
    this.bursts = [];
    this.rings = [];
    this.sparkTex = sparkTexture();
  }

  spawnBurst(pos, color, count = 10, speed = 5, size = 0.4, gravity = 4, life = 0.5) {
    const positions = new Float32Array(count * 3);
    const velocities = [];
    for (let i = 0; i < count; i++) {
      positions[i * 3] = pos.x + rand(-0.2, 0.2);
      positions[i * 3 + 1] = pos.y + rand(-0.2, 0.2);
      positions[i * 3 + 2] = pos.z + rand(-0.2, 0.2);
      const dir = new THREE.Vector3(rand(-1, 1), rand(-0.5, 1), rand(-1, 1)).normalize().multiplyScalar(rand(0.3, 1) * speed);
      velocities.push(dir);
    }
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const mat = new THREE.PointsMaterial({
      color, size, map: this.sparkTex, transparent: true, opacity: 1,
      blending: THREE.AdditiveBlending, depthWrite: false, sizeAttenuation: true,
    });
    const points = new THREE.Points(geo, mat);
    points.frustumCulled = false;
    this.game.scene.add(points);
    this.bursts.push({ points, velocities, gravity, life, maxLife: life, positions });
  }

  spawnBoost(car) {
    if (Math.random() > 0.55) return;
    const fwd = car.forward.clone();
    const right = car.right.clone();
    for (const side of [-1, 1]) {
      const pos = car.pos.clone().addScaledVector(fwd, -2.15).addScaledVector(right, side * 0.5);
      pos.y += 0.02;
      this.spawnBurst(pos, Math.random() < 0.5 ? 0xffb347 : 0xff7a1a, 1, 1.4, 0.45, -2, 0.35);
    }
  }

  spawnRing(pos, color, radius = 8) {
    const ring = new THREE.Mesh(
      new THREE.RingGeometry(0.8, 1, 48),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.9, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false })
    );
    ring.rotation.x = -Math.PI / 2;
    ring.position.copy(pos);
    ring.position.y = Math.max(0.12, pos.y - 0.5);
    this.game.scene.add(ring);
    this.rings.push({ mesh: ring, life: 0.65, maxLife: 0.65, radius });
  }

  update(dt) {
    for (let b = this.bursts.length - 1; b >= 0; b--) {
      const burst = this.bursts[b];
      burst.life -= dt;
      if (burst.life <= 0) {
        this.game.scene.remove(burst.points);
        burst.points.geometry.dispose();
        burst.points.material.dispose();
        this.bursts.splice(b, 1);
        continue;
      }
      const posAttr = burst.points.geometry.attributes.position;
      for (let i = 0; i < burst.velocities.length; i++) {
        const v = burst.velocities[i];
        burst.positions[i * 3] += v.x * dt;
        burst.positions[i * 3 + 1] += v.y * dt;
        burst.positions[i * 3 + 2] += v.z * dt;
        v.y -= burst.gravity * dt;
        v.multiplyScalar(1 - 0.6 * dt);
      }
      posAttr.needsUpdate = true;
      burst.points.material.opacity = Math.max(0, burst.life / burst.maxLife);
    }
    for (let i = this.rings.length - 1; i >= 0; i--) {
      const r = this.rings[i];
      r.life -= dt;
      if (r.life <= 0) {
        this.game.scene.remove(r.mesh);
        r.mesh.geometry.dispose();
        r.mesh.material.dispose();
        this.rings.splice(i, 1);
        continue;
      }
      const t = 1 - r.life / r.maxLife;
      const scale = 0.6 + t * r.radius;
      r.mesh.scale.setScalar(scale);
      r.mesh.material.opacity = (1 - t) * 0.75;
    }
  }
}

import * as THREE from 'three';
import { DIFFICULTY, FIELD, TEAM } from './constants.js';
import { clamp, wrapAngle } from './utils.js';

const _target = new THREE.Vector3();
const _dir = new THREE.Vector3();

export class AIController {
  update(car, game, dt) {
    const skill = DIFFICULTY[game.difficulty] || DIFFICULTY.pro;
    const idle = { throttle: 0, steer: 0, boost: false, jump: false };
    if (car.stun > 0) return idle;

    car.aiState.jumpCd = Math.max(0, car.aiState.jumpCd - dt);
    car.aiState.decision -= dt;
    car.aiState.itemCd = Math.max(0, (car.aiState.itemCd || 0) - dt);

    const ball = game.ball;
    const team = car.team;
    const enemyGoalZ = team === 'blue' ? FIELD.halfL : -FIELD.halfL;
    const ownGoalZ = TEAM[team].goalZ;

    const dxBall = ball.pos.x - car.pos.x;
    const dzBall = ball.pos.z - car.pos.z;
    const distBall = Math.hypot(dxBall, dzBall);
    const ownHalf = team === 'blue' ? ball.pos.z < 0 : ball.pos.z > 0;
    const veryCloseToOwnGoal = Math.abs(ball.pos.z - ownGoalZ) < 16;

    const isAttacker = car.role === 'attack';
    const attacking = isAttacker || (ownHalf && distBall < 30) || (car.role === 'support' && distBall < 12) || veryCloseToOwnGoal;

    _dir.set(-ball.pos.x, 0, enemyGoalZ - ball.pos.z).normalize();

    if (attacking) {
      // Stand behind the ball relative to the target goal, then drive through it.
      _target.set(ball.pos.x - _dir.x * 5.6, 0, ball.pos.z - _dir.z * 5.6);
      const behind = (car.pos.x - ball.pos.x) * _dir.x + (car.pos.z - ball.pos.z) * _dir.z;
      if (distBall < 8.2 && behind > -1.5) {
        _target.set(ball.pos.x + _dir.x * 1.5, 0, ball.pos.z + _dir.z * 1.5);
      }
    } else {
      // Defensive shape: sit between the ball and our own net.
      const guardZ = ownGoalZ + (team === 'blue' ? 14 : -14);
      _target.set(ball.pos.x * 0.52, 0, guardZ + (ball.pos.z - guardZ) * 0.18);
      if (ownHalf && distBall < 38) {
        _target.set(ball.pos.x - _dir.x * 6.5, 0, ball.pos.z - _dir.z * 6.5);
      }
    }

    // Grab a nearby item box when there is time and no item in the tank.
    if (!car.item) {
      let bestBox = null;
      let bestDist = 22;
      for (const box of game.itemBoxes) {
        if (!box.active) continue;
        const d = Math.hypot(box.group.position.x - car.pos.x, box.group.position.z - car.pos.z);
        if (d < bestDist) {
          bestDist = d;
          bestBox = box;
        }
      }
      if (bestBox && (distBall > 22 || !attacking) && Math.random() < 0.9) {
        _target.set(bestBox.group.position.x, 0, bestBox.group.position.z);
      }
    }

    const dx = _target.x - car.pos.x;
    const dz = _target.z - car.pos.z;
    const distTarget = Math.hypot(dx, dz);
    const desiredYaw = Math.atan2(dx, dz);
    const jitter = Math.sin(game.time * 2.1 + car.aiState.jitter) * 0.11 * (1 - skill.aim);
    const angle = wrapAngle(desiredYaw - car.yaw) + jitter;

    let steer = clamp(angle * (2.0 + skill.aim * 1.3), -1, 1);
    let throttle = 1;
    if (Math.abs(angle) > 1.75) throttle = 0.35;
    if (Math.abs(angle) > 2.45 && Math.abs(car.speed) < 12) {
      throttle = -0.65;
      steer = -clamp(angle, -1, 1);
    }
    if (distTarget < 3.2 && Math.abs(car.speed) > 22) throttle = 0.25;

    // unstuck
    const spd = Math.abs(car.speed);
    if (spd < 2.2 && distTarget > 5) car.aiState.stuck += dt;
    else car.aiState.stuck = Math.max(0, car.aiState.stuck - dt * 2);
    if (car.aiState.stuck > 0.9) {
      car.aiState.reverse = 0.7;
      car.aiState.stuck = 0;
    }
    if (car.aiState.reverse > 0) {
      car.aiState.reverse -= dt;
      return { throttle: -1, steer: -steer * 0.6, boost: false, jump: false };
    }

    // periodic boost decision
    if (car.aiState.decision <= 0) {
      car.aiState.decision = 0.45;
      car.aiState.wantBoost = Math.random() < skill.boost && car.boost > 12 && distTarget > 14 && Math.abs(angle) < 0.55;
    }

    // jump for high balls
    let jump = false;
    if (ball.pos.y > 3.1 && distBall < 7.5 && car.grounded && car.aiState.jumpCd <= 0 && Math.random() < skill.jump) {
      jump = true;
      car.aiState.jumpCd = 0.7;
    }

    this.#useItem(car, game, dt, { attacking, distBall, angle, skill, ball });

    return {
      throttle,
      steer,
      boost: !!car.aiState.wantBoost && car.boost > 0,
      jump,
    };
  }

  #useItem(car, game, dt, { attacking, distBall, angle, skill, ball }) {
    if (!car.hasItem()) return;
    if (!car.aiState.itemCd || car.aiState.itemCd <= 0) {
      let shouldUse = false;
      const item = car.item;
      if (item === 'mushroom' || item === 'star') {
        shouldUse = distBall < 34 && (attacking || Math.random() < 0.4);
      } else if (item === 'green') {
        shouldUse = Math.abs(angle) < 0.32 && distBall < 44;
      } else if (item === 'red') {
        const target = game.nearestOpponent(car);
        shouldUse = !!target && target.pos.distanceTo(ball.pos) < 60;
      } else if (item === 'banana') {
        shouldUse = !attacking || distBall > 20;
      } else if (item === 'lightning') {
        shouldUse = Math.random() < 0.02 || distBall < 26;
      } else if (item === 'bobomb') {
        shouldUse = distBall < 28 && Math.abs(angle) < 1.2;
      }
      if (shouldUse && Math.random() < 0.4 + skill.item * 0.6) {
        game.useItem(car);
        car.aiState.itemCd = 2.2;
      } else {
        car.aiState.itemCd = 0.6;
      }
    }
  }
}

import * as THREE from 'three';
import { AudioEngine } from './audio.js';
import { buildArena } from './arena.js';
import { AIController } from './ai.js';
import { Ball, BoostPad, Car, ItemBox, Particles, Projectile } from './entities.js';
import { BOOST_PADS, CAR, DIFFICULTY, FIELD, ITEM_BOX_SPOTS, ITEM_DEFS, ITEM_POOL, TEAM } from './constants.js';
import { clamp, damp, formatTime, pickWeighted, rand, wrapAngle } from './utils.js';

const KICKOFF = [
  { x: -10, z: -28, yaw: 0 },
  { x: 10, z: -33, yaw: 0 },
  { x: -10, z: 28, yaw: Math.PI },
  { x: 10, z: 33, yaw: Math.PI },
];

export class Game {
  constructor(canvas) {
    this.canvas = canvas;
    this.renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true,
      powerPreference: 'high-performance',
      alpha: false,
    });
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.75));
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.shadowMap.enabled = true;
    this.renderer.shadowMap.type = THREE.PCFSoftShadowMap;
    this.renderer.outputColorSpace = THREE.SRGBColorSpace;
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1.12;

    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0x02050b);
    this.camera = new THREE.PerspectiveCamera(68, window.innerWidth / window.innerHeight, 0.1, 420);
    this.camera.position.set(0, 25, 62);
    this.camLook = new THREE.Vector3(0, 3, 0);
    this.cameraShake = 0;
    this.fov = 68;

    this.sound = new AudioEngine();
    this.audio = this.sound;
    this.time = 0;
    this.lastFrame = performance.now();

    this.state = 'menu';
    this.pausedFrom = null;
    this.difficulty = 'pro';
    this.scores = { blue: 0, orange: 0 };
    this.matchTime = 180;
    this.overtime = false;
    this.countdown = 0;
    this.lastCount = 0;
    this.goalTimer = 0;
    this.pendingEnd = false;
    this.cameraMode = 'ball';
    this.stats = { goals: 0, items: 0, hits: 0, saves: 0 };
    this.msgTimer = 0;
    this.minimapAccum = 0;
    this.keys = new Set();
    this.jumpQueued = false;
    this.itemQueued = false;
    this.touch = { throttle: 0, steer: 0, boost: false };
    this.isTouch = window.matchMedia('(pointer: coarse)').matches || 'ontouchstart' in window;
    this.gamepadPrev = [];
    this.projectiles = [];
    this.itemBoxes = [];
    this.boostPads = [];

    this.ui = this.#cacheUI();

    this.arena = buildArena(this.scene);
    this.particles = new Particles(this);
    this.ball = new Ball(this);
    this.ai = new AIController();

    this.cars = [
      new Car(this, { team: 'blue', name: 'YOU', isPlayer: true }),
      new Car(this, { team: 'blue', name: 'KAI', isAI: true }),
      new Car(this, { team: 'orange', name: 'NOVA', isAI: true }),
      new Car(this, { team: 'orange', name: 'REX', isAI: true }),
    ];
    this.cars[1].role = 'support';
    this.cars[2].role = 'attack';
    this.cars[3].role = 'support';
    this.player = this.cars[0];

    for (const car of this.cars) {
      car.goals = 0;
      car.aiState.itemCd = 0;
      car.aiState.jumpCd = 0;
      this.scene.add(car.group);
    }

    for (const spot of ITEM_BOX_SPOTS) {
      const box = new ItemBox(this, spot.x, spot.z);
      this.itemBoxes.push(box);
      this.scene.add(box.group);
    }
    for (const pad of BOOST_PADS) {
      this.boostPads.push(new BoostPad(this, pad.x, pad.z, pad.big));
    }

    this.resetKickoff(true);
    this.#bindUI();
    this.#bindInput();
    this.#bindTouch();

    window.addEventListener('resize', () => this.#resize());
    document.addEventListener('visibilitychange', () => {
      if (document.hidden && this.state === 'play') this.togglePause(true);
    });

    this.updateHUD();
    this.loop = this.loop.bind(this);
    requestAnimationFrame(this.loop);

    // Exposed for debugging / automated verification.
    window.__turbo = this;
  }

  #cacheUI() {
    const $ = (id) => document.getElementById(id);
    return {
      hud: $('hud'),
      menu: $('menu'),
      loading: $('loading'),
      scoreBlue: $('score-blue'),
      scoreOrange: $('score-orange'),
      timer: $('timer'),
      clockSub: $('clock-sub'),
      overtime: $('overtime'),
      boostDial: $('boost-dial'),
      boostValue: $('boost-value'),
      speedValue: $('speed-value'),
      itemSlot: $('item-slot'),
      itemIcon: $('item-icon'),
      itemName: $('item-name'),
      center: $('center-msg'),
      sub: $('sub-msg'),
      feed: $('event-feed'),
      minimap: $('minimap'),
      pauseBtn: $('pause-btn'),
      camBtn: $('cam-btn'),
      touch: $('touch-controls'),
      joystickZone: $('joystick-zone'),
      joystickKnob: $('joystick-knob'),
      touchBoost: $('touch-boost'),
      touchJump: $('touch-jump'),
      touchItem: $('touch-item'),
      touchCam: $('touch-cam'),
      flash: $('goal-flash'),
      pauseScreen: $('pause-screen'),
      pauseBlue: $('pause-blue'),
      pauseOrange: $('pause-orange'),
      resultScreen: $('result-screen'),
      resultKicker: $('result-kicker'),
      resultTitle: $('result-title'),
      resultBlue: $('result-blue'),
      resultOrange: $('result-orange'),
      resultStats: $('result-stats'),
      playBtn: $('play-btn'),
      soundBtn: $('sound-btn'),
      difficulty: $('difficulty'),
      resumeBtn: $('resume-btn'),
      restartBtn: $('restart-btn'),
      quitBtn: $('quit-btn'),
      againBtn: $('again-btn'),
      menuBtn: $('menu-btn'),
    };
  }

  /* ═════════════════════ UI WIRING ═════════════════════ */
  #bindUI() {
    const ui = this.ui;
    ui.playBtn.addEventListener('click', () => this.startMatch());
    ui.soundBtn.addEventListener('click', () => {
      this.sound.init();
      this.sound.setEnabled(!this.sound.enabled);
      ui.soundBtn.classList.toggle('off', !this.sound.enabled);
      ui.soundBtn.innerHTML = `<span class="toggle-led"></span>SOUND ${this.sound.enabled ? 'ON' : 'OFF'}`;
      if (this.sound.enabled) this.sound.uiClick();
    });
    ui.difficulty.querySelectorAll('button').forEach((btn) => {
      btn.addEventListener('click', () => {
        this.difficulty = btn.dataset.difficulty;
        ui.difficulty.querySelectorAll('button').forEach((b) => b.classList.toggle('active', b === btn));
        this.sound.init();
        this.sound.uiClick();
      });
    });
    ui.pauseBtn.addEventListener('click', () => this.togglePause());
    ui.camBtn.addEventListener('click', () => this.toggleCamera());
    ui.resumeBtn.addEventListener('click', () => this.togglePause(true));
    ui.restartBtn.addEventListener('click', () => this.restartMatch());
    ui.quitBtn.addEventListener('click', () => this.quitToMenu());
    ui.againBtn.addEventListener('click', () => this.restartMatch());
    ui.menuBtn.addEventListener('click', () => this.quitToMenu());
    ui.touchCam.addEventListener('click', () => this.toggleCamera());

    document.addEventListener('pointerdown', () => this.sound.init(), { once: true });
    window.addEventListener('keydown', (e) => {
      if (e.code === 'Enter' && this.state === 'menu' && !e.repeat) {
        this.startMatch();
      }
    });
  }

  #bindInput() {
    const drivingKeys = new Set([
      'KeyW', 'KeyA', 'KeyS', 'KeyD', 'ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight',
      'Space', 'ShiftLeft', 'ShiftRight', 'KeyE', 'KeyC', 'KeyR',
    ]);
    window.addEventListener('keydown', (e) => {
      if (drivingKeys.has(e.code)) e.preventDefault();
      if (e.repeat) return;
      this.keys.add(e.code);
      if (this.state !== 'play' && this.state !== 'countdown') {
        if (e.code === 'Escape' || e.code === 'KeyP') this.togglePause();
        return;
      }
      if (e.code === 'Space') this.jumpQueued = true;
      if (e.code === 'KeyE') this.itemQueued = true;
      if (e.code === 'KeyC') this.toggleCamera();
      if (e.code === 'KeyR') this.resetPlayer();
      if (e.code === 'Escape' || e.code === 'KeyP') this.togglePause();
    });
    window.addEventListener('keyup', (e) => this.keys.delete(e.code));
    window.addEventListener('blur', () => this.keys.clear());
  }

  #bindTouch() {
    const zone = this.ui.joystickZone;
    const knob = this.ui.joystickKnob;
    let pointerId = null;

    const moveStick = (clientX, clientY) => {
      const rect = zone.getBoundingClientRect();
      const cx = rect.left + rect.width / 2;
      const cy = rect.top + rect.height / 2;
      const dx = clientX - cx;
      const dy = clientY - cy;
      const max = rect.width * 0.32;
      const len = Math.hypot(dx, dy);
      const k = len > max ? max / len : 1;
      const px = dx * k;
      const py = dy * k;
      knob.style.transform = `translate(${px}px, ${py}px)`;
      this.touch.steer = clamp(px / max, -1, 1);
      this.touch.throttle = clamp(-py / max, -1, 1);
    };

    zone.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      pointerId = e.pointerId;
      zone.setPointerCapture(pointerId);
      moveStick(e.clientX, e.clientY);
    });
    zone.addEventListener('pointermove', (e) => {
      if (e.pointerId === pointerId) moveStick(e.clientX, e.clientY);
    });
    const release = (e) => {
      if (e.pointerId !== pointerId) return;
      pointerId = null;
      knob.style.transform = 'translate(0px, 0px)';
      this.touch.steer = 0;
      this.touch.throttle = 0;
    };
    zone.addEventListener('pointerup', release);
    zone.addEventListener('pointercancel', release);

    const hold = (el, onDown, onUp) => {
      el.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        e.stopPropagation();
        el.classList.add('pressed');
        el.setPointerCapture(e.pointerId);
        onDown?.();
      });
      const up = (e) => {
        el.classList.remove('pressed');
        onUp?.();
      };
      el.addEventListener('pointerup', up);
      el.addEventListener('pointercancel', up);
      el.addEventListener('pointerleave', up);
    };

    hold(this.ui.touchBoost, () => { this.touch.boost = true; }, () => { this.touch.boost = false; });
    this.ui.touchJump.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      e.stopPropagation();
      this.jumpQueued = true;
      this.ui.touchJump.classList.add('pressed');
      setTimeout(() => this.ui.touchJump.classList.remove('pressed'), 110);
    });
    this.ui.touchItem.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      e.stopPropagation();
      this.itemQueued = true;
      this.ui.touchItem.classList.add('pressed');
      setTimeout(() => this.ui.touchItem.classList.remove('pressed'), 110);
    });
  }

  /* ═════════════════════ MATCH FLOW ═════════════════════ */
  startMatch(difficulty = this.difficulty) {
    this.difficulty = difficulty;
    this.sound.init();
    this.sound.uiClick();
    this.ui.menu.classList.add('closing');
    setTimeout(() => { this.ui.menu.style.display = 'none'; }, 430);
    this.ui.hud.classList.remove('hidden');
    if (this.isTouch) this.ui.touch.classList.remove('hidden');
    this.ui.pauseScreen.classList.add('hidden');
    this.ui.resultScreen.classList.add('hidden');
    this.ui.flash.classList.remove('on');
    if (this.ui.feed) this.ui.feed.innerHTML = '';

    this.scores.blue = 0;
    this.scores.orange = 0;
    this.matchTime = 180;
    this.overtime = false;
    this.pendingEnd = false;
    this.stats = { goals: 0, items: 0, hits: 0, saves: 0 };
    for (const car of this.cars) { car.goals = 0; }
    this.clearProjectiles();
    this.resetKickoff(true);
    this.state = 'countdown';
    this.startCountdown(3.0);
    this.#snapCamera();
    this.updateHUD();
  }

  restartMatch() {
    this.ui.pauseScreen.classList.add('hidden');
    this.ui.resultScreen.classList.add('hidden');
    if (this.ui.menu) this.ui.menu.style.display = 'none';
    this.ui.hud.classList.remove('hidden');
    this.state = 'menu';
    this.startMatch(this.difficulty);
  }

  quitToMenu() {
    this.state = 'menu';
    this.scores.blue = 0;
    this.scores.orange = 0;
    this.matchTime = 180;
    this.overtime = false;
    this.pendingEnd = false;
    this.clearProjectiles();
    this.resetKickoff(true);
    this.ui.hud.classList.add('hidden');
    this.ui.touch.classList.add('hidden');
    this.ui.pauseScreen.classList.add('hidden');
    this.ui.resultScreen.classList.add('hidden');
    this.ui.flash.classList.remove('on');
    this.ui.menu.style.display = 'flex';
    this.ui.menu.classList.remove('closing');
    this.ui.feed.innerHTML = '';
    this.clearMessages();
    this.cameraMode = 'ball';
    this.ui.camBtn.textContent = 'CAM · BALL';
    this.sound.setEngine(0, false, false);
    this.updateHUD();
  }

  togglePause(forceResume = false) {
    if (forceResume && this.state === 'paused') {
      this.state = this.pausedFrom || 'play';
      this.pausedFrom = null;
      this.ui.pauseScreen.classList.add('hidden');
      if (this.isTouch) this.ui.touch.classList.remove('hidden');
      this.sound.uiClick();
      return;
    }
    if (this.state === 'paused') {
      this.state = this.pausedFrom || 'play';
      this.pausedFrom = null;
      this.ui.pauseScreen.classList.add('hidden');
      if (this.isTouch) this.ui.touch.classList.remove('hidden');
      this.sound.uiClick();
      return;
    }
    if (this.state === 'play' || this.state === 'countdown' || this.state === 'goal') {
      this.pausedFrom = this.state;
      this.state = 'paused';
      this.ui.pauseBlue.textContent = this.scores.blue;
      this.ui.pauseOrange.textContent = this.scores.orange;
      this.ui.pauseScreen.classList.remove('hidden');
      this.ui.touch.classList.add('hidden');
      this.sound.setEngine(0, false, false);
      this.sound.uiClick();
    }
  }

  startCountdown(seconds = 2.6) {
    this.state = 'countdown';
    this.countdown = seconds;
    this.lastCount = Math.ceil(seconds);
    this.announce(String(Math.min(3, this.lastCount)), 'GET READY', '', 0.9);
    this.sound.countdown(false);
  }

  resetPlayer() {
    if (this.state !== 'play') return;
    const car = this.player;
    if (car.stun > 0) return;
    const z = TEAM.blue.goalZ + 12;
    car.reset(0, z, 0, false);
    car.boost = Math.max(car.boost, 20);
    this.particles.spawnRing(new THREE.Vector3(0, 0.1, z), TEAM.blue.color, 4);
    this.addFeed('YOU — RESET', 'blue');
    this.dropCameraSoon = true;
  }

  toggleCamera() {
    this.cameraMode = this.cameraMode === 'ball' ? 'car' : 'ball';
    this.ui.camBtn.textContent = this.cameraMode === 'ball' ? 'CAM · BALL' : 'CAM · CAR';
    this.sound.uiClick();
  }

  /* ═════════════════════ MAIN LOOP ═════════════════════ */
  loop(now) {
    requestAnimationFrame(this.loop);
    const dt = Math.min(0.05, Math.max(0.0001, (now - this.lastFrame) / 1000));
    this.lastFrame = now;
    this.time += dt;

    this.arena.update(this.time);
    this.particles.update(dt);
    for (const box of this.itemBoxes) box.update(dt, this.time);
    for (const pad of this.boostPads) pad.update(dt);

    if (this.state === 'menu') {
      this.#updateMenuCamera(dt);
      this.renderer.render(this.scene, this.camera);
      return;
    }

    if (this.state === 'paused') {
      this.renderer.render(this.scene, this.camera);
      return;
    }

    if (this.state === 'play') {
      this.#updatePlay(dt);
    } else if (this.state === 'countdown') {
      this.#updateCountdown(dt);
    } else if (this.state === 'goal') {
      this.#updateGoalState(dt);
    } else if (this.state === 'ended') {
      this.#updateEnded(dt);
    }

    this.#updateMessages(dt);
    this.#updateCamera(dt);
    this.#updateHUD(dt);
    this.renderer.render(this.scene, this.camera);
  }

  #updateMenuCamera(dt) {
    const a = this.time * 0.09;
    const r = 58;
    const desired = new THREE.Vector3(Math.sin(a) * r, 23 + Math.sin(this.time * 0.22) * 1.8, Math.cos(a) * r);
    const t = 1 - Math.exp(-1.6 * dt);
    this.camera.position.lerp(desired, t);
    this.camLook.lerp(new THREE.Vector3(0, 4.4, 0), t);
    this.camera.lookAt(this.camLook);
    this.camera.fov = 55;
    this.camera.updateProjectionMatrix();
    this.sound.setEngine(0, false, false);
    this.ball.ring.material.opacity = 0.25;
  }

  #updateCountdown(dt) {
    this.countdown -= dt;
    const n = Math.ceil(this.countdown);
    if (n !== this.lastCount && n > 0) {
      this.lastCount = n;
      this.announce(String(n), 'GET READY', '', 0.9);
      this.sound.countdown(false);
    }
    if (this.countdown <= 0) {
      this.state = 'play';
      this.announce('GO!', this.overtime ? 'GOLDEN GOAL' : 'KICK OFF', 'gold', 0.85);
      this.sound.countdown(true);
      this.sound.setEngine(0, false, true);
    }
    this.#updateTouchCamera(dt, true);
    this.sound.setEngine(0, false, false);
  }

  #updatePlay(dt) {
    // player actions
    if (this.itemQueued) {
      this.itemQueued = false;
      this.useItem(this.player);
    }
    const playerCtrl = this.#playerControls();
    this.#pollGamepad();

    for (const car of this.cars) {
      let ctrl = { throttle: 0, steer: 0, boost: false, jump: false };
      if (car.isPlayer) ctrl = playerCtrl;
      else if (car.isAI) ctrl = this.ai.update(car, this, dt);
      car.update(ctrl, dt, this);
    }
    this.jumpQueued = false;
    this.itemQueued = false;

    // roulette completion sounds
    for (const car of this.cars) {
      if (car.itemRolling > 0) {
        car._wasRolling = true;
      } else if (car._wasRolling) {
        car._wasRolling = false;
        if (car.item) {
          this.sound.itemReady();
          if (car.isPlayer) this.addFeed(`${ITEM_DEFS[car.item].icon} ${ITEM_DEFS[car.item].name} READY`, car.team);
        }
      }
    }

    this.#carCarCollisions(dt);

    this.ball.update(dt);
    for (const car of this.cars) {
      if (this.state !== 'play') break;
      this.ball.collideCar(car);
    }

    if (this.state === 'play') this.#checkGoal();

    // pickups
    for (const car of this.cars) {
      if (!car.item) {
        for (const box of this.itemBoxes) {
          if (!box.active) continue;
          const dx = car.pos.x - box.group.position.x;
          const dz = car.pos.z - box.group.position.z;
          if (dx * dx + dz * dz < 7.6) {
            if (box.collect()) {
              const item = this.#rollItem(car);
              car.giveItem(item);
              car.aiState.itemCd = rand(0.8, 2.2);
              if (car.isPlayer) {
                this.ui.itemSlot.classList.add('rolling');
                this.addFeed(`${ITEM_DEFS[item].icon} ITEM ACQUIRED`, car.team);
              }
            }
            break;
          }
        }
      }
      for (const pad of this.boostPads) pad.tryCollect(car);
    }

    this.#updateProjectiles(dt);

    // timer
    if (!this.overtime) {
      this.matchTime -= dt;
      if (this.matchTime <= 0) {
        this.matchTime = 0;
        if (this.scores.blue === this.scores.orange) {
          this.overtime = true;
          this.announce('OVERTIME', 'NEXT GOAL WINS', 'gold', 2.8);
          this.sound.whistle();
          this.addFeed('OVERTIME — GOLDEN GOAL', 'gold');
        } else {
          this.endMatch();
          return;
        }
      }
    }

    // engine sound
    this.sound.setEngine(this.player.speedNorm, this.player.boosting, true);
  }

  #updateGoalState(dt) {
    this.ball.update(dt);
    const idle = { throttle: 0, steer: 0, boost: false, jump: false };
    for (const car of this.cars) car.update(idle, dt, this);
    this.#updateProjectiles(dt);
    this.goalTimer -= dt;
    this.sound.setEngine(0, false, false);
    this.#updateTouchCamera(dt, true);
    if (this.goalTimer <= 0) {
      if (this.pendingEnd) {
        this.endMatch();
      } else {
        this.resetKickoff(false);
        this.startCountdown(2.6);
      }
    }
  }

  #updateEnded(dt) {
    const idle = { throttle: 0, steer: 0, boost: false, jump: false };
    for (const car of this.cars) car.update(idle, dt, this);
    this.ball.update(dt);
    this.sound.setEngine(0, false, false);
    this.#updateTouchCamera(dt, true);
  }

  #updateTouchCamera(dt, freeze) {
    if (freeze) {
      this.player.speed = 0;
      this.player.vel.set(0, 0, 0);
    }
  }

  /* ═════════════════════ INPUT ═════════════════════ */
  #playerControls() {
    const k = this.keys;
    let throttle = 0;
    let steer = 0;
    if (k.has('KeyW') || k.has('ArrowUp')) throttle += 1;
    if (k.has('KeyS') || k.has('ArrowDown')) throttle -= 1;
    if (k.has('KeyD') || k.has('ArrowRight')) steer += 1;
    if (k.has('KeyA') || k.has('ArrowLeft')) steer -= 1;
    throttle += this.touch.throttle;
    steer += this.touch.steer;
    const boost = !!(k.has('ShiftLeft') || k.has('ShiftRight') || this.touch.boost);
    return {
      throttle: clamp(throttle, -1, 1),
      steer: clamp(steer, -1, 1),
      boost,
      jump: this.jumpQueued,
    };
  }

  #pollGamepad() {
    if (!navigator.getGamepads) return;
    const pads = navigator.getGamepads();
    const gp = pads && pads[0];
    if (!gp) return;
    const dead = 0.18;
    const ax = gp.axes[0] || 0;
    const ay = gp.axes[1] || 0;
    if (Math.abs(ax) > dead) this.touch.steer = clamp(this.touch.steer + ax * 0.9, -1, 1);
    if (Math.abs(ay) > dead) this.touch.throttle = clamp(this.touch.throttle - ay * 0.9, -1, 1);
    const btn = (i) => gp.buttons[i] && gp.buttons[i].pressed;
    if (btn(6) || btn(7)) this.touch.boost = true;
    else if (!this.isTouch) this.touch.boost = false;
    if (btn(0) && !this.gamepadPrev[0]) this.jumpQueued = true;
    if (btn(2) && !this.gamepadPrev[2]) this.itemQueued = true;
    if (btn(3) && !this.gamepadPrev[3]) this.toggleCamera();
    for (let i = 0; i < 8; i++) this.gamepadPrev[i] = btn(i);
    // throttle decays back to keys-only when the stick is centered
    if (Math.abs(ay) <= dead && !this.isTouch) this.touch.throttle = 0;
    if (Math.abs(ax) <= dead && !this.isTouch) this.touch.steer = 0;
  }

  /* ═════════════════════ PHYSICS HELPERS ═════════════════════ */
  #carCarCollisions(dt) {
    for (let i = 0; i < this.cars.length; i++) {
      for (let j = i + 1; j < this.cars.length; j++) {
        const a = this.cars[i];
        const b = this.cars[j];
        if (Math.abs(a.pos.y - b.pos.y) > 2.4) continue;
        let dx = b.pos.x - a.pos.x;
        let dz = b.pos.z - a.pos.z;
        let dist = Math.hypot(dx, dz);
        const minDist = 2.45;
        if (dist >= minDist) continue;
        if (dist < 0.001) { dx = 1; dz = 0; dist = 1; }
        const nx = dx / dist;
        const nz = dz / dist;
        const overlap = minDist - dist;
        a.pos.x -= nx * overlap * 0.5;
        a.pos.z -= nz * overlap * 0.5;
        b.pos.x += nx * overlap * 0.5;
        b.pos.z += nz * overlap * 0.5;

        const avx = a.vel.x;
        const avz = a.vel.z;
        const bvx = b.vel.x;
        const bvz = b.vel.z;
        const rel = (avx - bvx) * nx + (avz - bvz) * nz;
        if (rel > 0) {
          const impulse = rel * 0.5;
          a.vel.x -= nx * impulse;
          a.vel.z -= nz * impulse;
          b.vel.x += nx * impulse;
          b.vel.z += nz * impulse;
        }
        const impact = Math.abs(rel);
        if (impact > 7) {
          this.sound.hit(clamp(impact / 40, 0.15, 0.8));
          this.cameraShake = Math.max(this.cameraShake, 0.1);
          this.particles.spawnBurst(new THREE.Vector3((a.pos.x + b.pos.x) / 2, 1, (a.pos.z + b.pos.z) / 2), 0xcfe8f8, 6, 3, 0.3, 6, 0.35);
        }
        // star power smacks opponents
        if (a.invincible > 0 && b.invincible <= 0 && a.team !== b.team) {
          if (b.stunCar(1.3, 1)) {
            this.sound.hit(1);
            this.addFeed(`${a.name} STAR SMASH`, a.team);
          }
        }
        if (b.invincible > 0 && a.invincible <= 0 && a.team !== b.team) {
          if (a.stunCar(1.3, -1)) {
            this.sound.hit(1);
            this.addFeed(`${b.name} STAR SMASH`, b.team);
          }
        }
      }
    }
  }

  #checkGoal() {
    if (this.state !== 'play') return;
    const b = this.ball;
    if (b.pos.z > FIELD.halfL + 0.75 && Math.abs(b.pos.x) < FIELD.goalHalfW + 1 && b.pos.y < FIELD.goalH + 1) {
      this.scoreGoal('blue');
    } else if (b.pos.z < -FIELD.halfL - 0.75 && Math.abs(b.pos.x) < FIELD.goalHalfW + 1 && b.pos.y < FIELD.goalH + 1) {
      this.scoreGoal('orange');
    }
  }

  scoreGoal(team) {
    if (this.state !== 'play') return;
    this.scores[team]++;
    this.state = 'goal';
    this.goalTimer = 3.0;
    this.pendingEnd = this.scores[team] >= 5 || this.overtime;

    const scorer = this.ball.lastTouchCar && this.ball.lastTouchCar.team === team ? this.ball.lastTouchCar : null;
    if (scorer) {
      scorer.goals++;
      if (scorer.isPlayer) this.stats.goals++;
    }
    const label = team === 'blue' ? 'BLUE GOAL!' : 'ORANGE GOAL!';
    const sub = scorer ? `${scorer.name}${scorer.isPlayer ? ' SCORES' : ' FINISHES'}` : 'OWN GOAL';
    this.announce(label, sub, team === 'blue' ? 'goal-blue' : 'goal-orange', 2.7);
    this.addFeed(`${label} ${this.scores.blue} — ${this.scores.orange}`, team);
    this.sound.goal(team);
    this.cameraShake = 1.15;

    const goalPos = new THREE.Vector3(this.ball.pos.x, Math.max(2, this.ball.pos.y), team === 'blue' ? FIELD.halfL + 1 : -FIELD.halfL - 1);
    this.particles.spawnBurst(goalPos, TEAM[team].color, 60, 16, 0.7, 7, 1.3);
    this.particles.spawnBurst(goalPos, 0xffffff, 25, 9, 0.5, 9, 0.9);
    this.particles.spawnRing(new THREE.Vector3(goalPos.x, 0.1, goalPos.z), TEAM[team].color, 22);

    this.ui.flash.style.background = `radial-gradient(circle at 50% 50%, rgba(255,255,255,0.55), ${team === 'blue' ? 'rgba(49,184,255,0.28)' : 'rgba(255,122,36,0.28)'} 45%, transparent 72%)`;
    this.ui.flash.classList.add('on');
    setTimeout(() => this.ui.flash.classList.remove('on'), 480);
    this.updateHUD();
  }

  endMatch() {
    if (this.state === 'ended') return;
    this.state = 'ended';
    this.ui.touch.classList.add('hidden');
    this.sound.whistle();
    this.sound.setEngine(0, false, false);
    const blue = this.scores.blue;
    const orange = this.scores.orange;
    const winner = blue === orange ? null : blue > orange ? 'blue' : 'orange';
    this.ui.resultKicker.textContent = this.overtime ? 'GOLDEN GOAL · MATCH COMPLETE' : 'MATCH COMPLETE';
    this.ui.resultTitle.textContent = winner ? `${TEAM[winner].name} WINS` : 'DRAW';
    this.ui.resultTitle.style.color = winner === 'orange' ? '#ffb167' : winner === 'blue' ? '#8bdcff' : '#eaf7ff';
    this.ui.resultBlue.textContent = blue;
    this.ui.resultOrange.textContent = orange;
    const top = [...this.cars].sort((a, b) => b.goals - a.goals)[0];
    const parts = [];
    if (top && top.goals > 0) parts.push(`${top.name} LED THE SCOREBOARD WITH ${top.goals}`);
    parts.push(`YOU · ${this.stats.goals} GOALS · ${this.stats.items} ITEMS · ${this.stats.hits} SHELL HITS`);
    this.ui.resultStats.textContent = parts.join(' // ');
    this.ui.resultScreen.classList.remove('hidden');
    this.ui.hud.classList.add('hidden');
  }

  resetKickoff(first) {
    this.cars.forEach((car, i) => {
      const spawn = KICKOFF[i];
      car.reset(spawn.x, spawn.z, spawn.yaw, true);
      car.goals = car.goals || 0;
      car.group.visible = true;
    });
    this.ball.reset(0, FIELD.ballRadius, 0);
    this.clearProjectiles();
    for (const box of this.itemBoxes) {
      box.active = true;
      box.group.visible = true;
      box.respawn = 0;
    }
    for (const pad of this.boostPads) {
      pad.active = true;
      pad.group.visible = true;
      pad.respawn = 0;
    }
    this.ui.flash.classList.remove('on');
    if (first) {
      this.player.boost = 50;
    }
  }

  clearProjectiles() {
    for (const p of this.projectiles) {
      this.scene.remove(p.group);
    }
    this.projectiles = [];
  }

  /* ═════════════════════ ITEMS ═════════════════════ */
  #rollItem(car) {
    const opp = car.team === 'blue' ? this.scores.orange : this.scores.blue;
    const own = this.scores[car.team];
    const behind = opp - own;
    const entries = ITEM_POOL.map((e) => ({ ...e }));
    if (behind > 0) {
      for (const e of entries) {
        if (e.id === 'mushroom') e.w += 7;
        if (e.id === 'star') e.w += 5;
        if (e.id === 'red') e.w += 4;
        if (e.id === 'lightning') e.w += 4;
        if (e.id === 'banana') e.w -= 3;
      }
    } else if (behind < 0) {
      for (const e of entries) {
        if (e.id === 'banana') e.w += 5;
        if (e.id === 'green') e.w += 4;
        if (e.id === 'star') e.w -= 2;
      }
    }
    return pickWeighted(entries);
  }

  useItem(car) {
    if (!car.hasItem()) return;
    if (this.state !== 'play' && this.state !== 'countdown') return;
    const item = car.item;
    car.item = null;
    car.itemRolling = 0;
    car._wasRolling = false;
    const def = ITEM_DEFS[item];
    const team = TEAM[car.team];
    this.ui.itemSlot.classList.remove('rolling');

    if (car.isPlayer) {
      this.stats.items++;
      this.addFeed(`${def.icon} ${def.name}`, car.team);
    }
    this.sound.itemUse();

    const fwd = car.forward.clone();
    const origin = car.pos.clone();

    if (item === 'mushroom') {
      car.speedTimer = Math.max(car.speedTimer, 2.7);
      car.boost = Math.min(100, car.boost + 40);
      if (car.grounded) car.speed = Math.min(52, car.speed + 9);
      this.particles.spawnRing(origin.clone(), 0xffd36a, 5);
      this.particles.spawnBurst(origin.clone().setY(1), 0xffd36a, 18, 8, 0.4, 3, 0.8);
      this.sound.boostStart();
      if (car.isPlayer) this.cameraShake = Math.max(this.cameraShake, 0.2);
    } else if (item === 'star') {
      car.invincible = 6.5;
      car.speedTimer = Math.max(car.speedTimer, 6.5);
      this.particles.spawnBurst(origin.clone().setY(1.5), 0xffe37a, 26, 9, 0.45, 3, 1);
      this.particles.spawnRing(origin.clone(), 0xffe37a, 7);
      this.sound.star();
    } else if (item === 'green' || item === 'red') {
      const pos = origin.clone().addScaledVector(fwd, 2.8);
      pos.y = 1.15;
      let vel = fwd.clone().multiplyScalar(56);
      let target = null;
      if (item === 'red') {
        target = this.nearestOpponent(car);
        if (target) {
          const dir = target.pos.clone().sub(pos);
          dir.y = 0;
          if (dir.lengthSq() > 0.01) vel = dir.normalize().multiplyScalar(47);
        }
      }
      vel.x += car.vel.x * 0.45;
      vel.z += car.vel.z * 0.45;
      const proj = new Projectile(this, item, pos, vel, car);
      proj.target = target;
      proj.spawnTime = this.time;
      this.projectiles.push(proj);
      this.sound.shell();
      this.particles.spawnBurst(pos.clone(), item === 'green' ? 0x45e06b : 0xff4444, 10, 4, 0.3, 2, 0.4);
    } else if (item === 'banana') {
      const pos = origin.clone().addScaledVector(fwd, -3.6);
      pos.y = 0.5;
      const proj = new Projectile(this, 'banana', pos, new THREE.Vector3(), car);
      proj.spawnTime = this.time;
      this.projectiles.push(proj);
      this.sound.banana();
    } else if (item === 'bobomb') {
      const pos = origin.clone().addScaledVector(fwd, 3.0);
      pos.y = 1.4;
      const vel = fwd.clone().multiplyScalar(30);
      vel.y = 13;
      vel.add(car.vel.clone().multiplyScalar(0.4));
      const proj = new Projectile(this, 'bobomb', pos, vel, car);
      proj.spawnTime = this.time;
      this.projectiles.push(proj);
      this.sound.shell();
    } else if (item === 'lightning') {
      const opponents = this.cars.filter((c) => c.team !== car.team);
      for (const opp of opponents) {
        if (opp.invincible > 0) continue;
        opp.shrinkTimer = 5.8;
        opp.speed *= 0.4;
        opp.stunCar(0.45, 1);
      }
      this.ui.flash.style.background = 'radial-gradient(circle at 50% 40%, rgba(255,255,255,0.95), rgba(139,124,255,0.45) 40%, transparent 75%)';
      this.ui.flash.classList.add('on');
      setTimeout(() => this.ui.flash.classList.remove('on'), 260);
      this.cameraShake = 0.8;
      this.sound.lightning();
      this.addFeed('⚡ LIGHTNING — RIVALS SHRUNK', car.team);
    }

    this.updateHUD();
  }

  nearestOpponent(car) {
    let best = null;
    let bestDist = Infinity;
    for (const other of this.cars) {
      if (other.team === car.team) continue;
      const d = other.pos.distanceToSquared(car.pos);
      if (d < bestDist) {
        best = other;
        bestDist = d;
      }
    }
    return best;
  }

  #updateProjectiles(dt) {
    for (const p of this.projectiles) {
      if (p.dead) continue;
      p.update(dt, this);
      if (p.dead) continue;

      if (p.type === 'banana') {
        const grace = this.time - (p.spawnTime || 0) < 0.9;
        for (const car of this.cars) {
          if (grace && car === p.owner) continue;
          const d = Math.hypot(car.pos.x - p.pos.x, car.pos.z - p.pos.z);
          if (d < 2.2 && Math.abs(car.pos.y - p.pos.y) < 2.2) {
            if (car.invincible <= 0) {
              car.stunCar(1.15, Math.random() < 0.5 ? 1 : -1);
              this.sound.banana();
              this.particles.spawnBurst(p.pos.clone(), 0xffd23f, 12, 5, 0.35, 6, 0.55);
              this.addFeed(`${car.name} SLIPPED ON A BANANA`, car.team === 'blue' ? 'orange' : 'blue');
            }
            p.die();
            break;
          }
        }
        continue;
      }

      if (p.type === 'green' || p.type === 'red') {
        // shell vs ball
        const dBall = p.pos.distanceTo(this.ball.pos);
        if (dBall < this.ball.radius + p.radius + 0.15) {
          const dir = this.ball.pos.clone().sub(p.pos).normalize();
          this.ball.kick(dir.multiplyScalar(40).add(new THREE.Vector3(0, 12, 0)));
          this.ball.vel.addScaledVector(p.vel, 0.3);
          this.particles.spawnBurst(p.pos.clone(), p.type === 'green' ? 0x45e06b : 0xff4444, 20, 9, 0.4, 4, 0.65);
          this.sound.hit(0.9);
          this.cameraShake = Math.max(this.cameraShake, 0.25);
          p.die(true);
          continue;
        }
        for (const car of this.cars) {
          if (car === p.owner) continue;
          if (car.team === p.owner?.team) continue;
          const d = p.pos.distanceTo(car.pos);
          if (d < 2.35) {
            if (car.invincible <= 0) {
              car.stunCar(1.25, Math.random() < 0.5 ? 1 : -1);
              this.particles.spawnBurst(car.pos.clone().setY(1.2), p.type === 'green' ? 0x45e06b : 0xff4444, 16, 6, 0.4, 5, 0.6);
              this.sound.hit(1);
              this.cameraShake = Math.max(this.cameraShake, 0.3);
              if (p.owner?.isPlayer) this.stats.hits++;
              this.addFeed(`${p.owner?.name || 'SHELL'} HIT ${car.name}`, car.team === 'blue' ? 'orange' : 'blue');
            }
            p.die(true);
            break;
          }
        }
      }
    }
    this.projectiles = this.projectiles.filter((p) => !p.dead);
  }

  explodeBobomb(pos, owner) {
    this.sound.explosion();
    this.cameraShake = Math.max(this.cameraShake, 1);
    this.particles.spawnBurst(pos.clone(), 0xff8a3d, 55, 16, 0.7, 9, 1.1);
    this.particles.spawnBurst(pos.clone(), 0xffe09a, 24, 9, 0.5, 7, 0.8);
    this.particles.spawnRing(new THREE.Vector3(pos.x, 0.1, pos.z), 0xff8a3d, 18);
    this.ui.flash.style.background = 'radial-gradient(circle at 50% 50%, rgba(255,220,160,0.65), rgba(255,110,30,0.28) 45%, transparent 72%)';
    this.ui.flash.classList.add('on');
    setTimeout(() => this.ui.flash.classList.remove('on'), 240);

    const ballDist = pos.distanceTo(this.ball.pos);
    if (ballDist < 14) {
      const dir = this.ball.pos.clone().sub(pos).normalize();
      const power = (1 - ballDist / 14) * 44 + 14;
      this.ball.kick(dir.multiplyScalar(power).add(new THREE.Vector3(0, 16, 0)));
    }
    for (const car of this.cars) {
      if (car === owner) continue;
      const d = car.pos.distanceTo(pos);
      if (d < 11) {
        const dir = car.pos.clone().sub(pos).normalize();
        if (car.invincible <= 0) car.stunCar(1.4, Math.random() < 0.5 ? 1 : -1);
        car.vel.x += dir.x * 18;
        car.vel.z += dir.z * 18;
        car.vy = Math.max(car.vy, 8.5);
        car.grounded = false;
        car.boost = Math.max(0, car.boost - 20);
      }
    }
  }

  /* ═════════════════════ CAMERA ═════════════════════ */
  #snapCamera() {
    const p = this.player;
    const fwd = p.forward.clone();
    this.camera.position.copy(p.pos).addScaledVector(fwd, -11.5).add(new THREE.Vector3(0, 5.1, 0));
    this.camLook.copy(this.ball.pos);
    this.camera.lookAt(this.camLook);
    this.camera.fov = 68;
    this.camera.updateProjectionMatrix();
  }

  #updateCamera(dt) {
    const p = this.player;
    const fwd = p.forward.clone();
    const speedNorm = p.speedNorm;
    const boosting = p.boosting;
    const dist = 11.0 + speedNorm * 1.7;
    const height = 4.9 + speedNorm * 0.5;

    const desired = p.pos.clone().addScaledVector(fwd, -dist);
    desired.y += height;

    // small lateral offset for steering feel
    const right = p.right.clone();
    desired.addScaledVector(right, -this.#steerOffset(p) * 0.8);

    const look = new THREE.Vector3();
    if (this.cameraMode === 'ball') {
      look.copy(this.ball.pos).addScaledVector(this.ball.vel, 0.055);
      if (this.ball.pos.y < 2.4) look.y = 2.4;
    } else {
      look.copy(p.pos).addScaledVector(fwd, 10);
      look.y = p.pos.y + 1.4;
    }

    const posLerp = this.dropCameraSoon ? 1 : 1 - Math.exp(-7.5 * dt);
    this.dropCameraSoon = false;
    this.camera.position.lerp(desired, posLerp);
    this.camLook.lerp(look, 1 - Math.exp(-10 * dt));

    // keep the camera inside the arena walls a little
    this.camera.position.x = clamp(this.camera.position.x, -FIELD.halfW + 1.2, FIELD.halfW - 1.2);
    this.camera.position.z = clamp(this.camera.position.z, -FIELD.halfL + 1.2, FIELD.halfL - 1.2);
    this.camera.position.y = clamp(this.camera.position.y, 2.2, FIELD.wallH + 10);

    this.cameraShake = Math.max(0, this.cameraShake - dt * 2.2);
    if (this.cameraShake > 0.002) {
      const s = this.cameraShake * 0.55;
      this.camera.position.x += rand(-s, s);
      this.camera.position.y += rand(-s, s);
      this.camera.position.z += rand(-s, s);
    }

    const targetFov = 68 + speedNorm * 8 + (boosting ? 3 : 0);
    this.fov = damp(this.fov, targetFov, 5, dt);
    if (Math.abs(this.camera.fov - this.fov) > 0.01) {
      this.camera.fov = this.fov;
      this.camera.updateProjectionMatrix();
    }
    this.camera.lookAt(this.camLook);
  }

  #steerOffset(car) {
    const k = this.keys;
    let steer = 0;
    if (k.has('KeyD') || k.has('ArrowRight')) steer += 1;
    if (k.has('KeyA') || k.has('ArrowLeft')) steer -= 1;
    steer += this.touch.steer;
    return clamp(steer, -1, 1);
  }

  /* ═════════════════════ MESSAGES + HUD ═════════════════════ */
  announce(text, sub = '', cls = '', duration = 1.4) {
    const el = this.ui.center;
    el.className = 'center-msg ' + cls;
    void el.offsetWidth;
    el.textContent = text;
    el.classList.add('show');
    const subEl = this.ui.sub;
    subEl.className = 'sub-msg';
    void subEl.offsetWidth;
    subEl.textContent = sub;
    if (sub) subEl.classList.add('show');
    this.msgTimer = duration;
  }

  clearMessages() {
    this.ui.center.className = 'center-msg';
    this.ui.sub.className = 'sub-msg';
    this.msgTimer = 0;
  }

  #updateMessages(dt) {
    if (this.msgTimer > 0) {
      this.msgTimer -= dt;
      if (this.msgTimer <= 0) {
        this.ui.center.classList.remove('show');
        this.ui.sub.classList.remove('show');
      }
    }
  }

  addFeed(text, team = '') {
    if (!this.ui.feed) return;
    const item = document.createElement('div');
    item.className = 'feed-item ' + team;
    item.textContent = text;
    this.ui.feed.prepend(item);
    while (this.ui.feed.children.length > 3) this.ui.feed.lastChild.remove();
    setTimeout(() => {
      item.style.opacity = '0';
      item.style.transition = 'opacity 0.4s';
      setTimeout(() => item.remove(), 420);
    }, 3200);
  }

  updateHUD(dt = 0) {
    const p = this.player;
    const ui = this.ui;

    ui.scoreBlue.textContent = this.scores.blue;
    ui.scoreOrange.textContent = this.scores.orange;
    const timeText = formatTime(this.matchTime);
    ui.timer.textContent = timeText;
    ui.timer.classList.toggle('warn', this.matchTime <= 30 && !this.overtime && this.state !== 'menu');
    ui.overtime.classList.toggle('hidden', !this.overtime);
    ui.clockSub.textContent = this.overtime ? 'GOLDEN GOAL' : 'FIRST TO 5';

    const boost = Math.round(p.boost);
    ui.boostDial.style.setProperty('--boost', boost);
    ui.boostValue.textContent = boost;
    ui.boostDial.classList.toggle('low', boost < 20);
    ui.speedValue.textContent = Math.round(Math.abs(p.speed) * 6.2);

    if (this.state === 'menu') {
      ui.itemIcon.textContent = '?';
      ui.itemName.textContent = 'NO ITEM';
      ui.itemName.classList.remove('ready');
      ui.itemSlot.classList.remove('ready', 'rolling');
      return;
    }

    if (p.itemRolling > 0) {
      const ids = Object.keys(ITEM_DEFS);
      const idx = Math.floor(this.time * 16) % ids.length;
      ui.itemIcon.textContent = ITEM_DEFS[ids[idx]].icon;
      ui.itemName.textContent = 'ROLLING...';
      ui.itemName.classList.remove('ready');
      ui.itemSlot.classList.add('rolling');
      ui.itemSlot.classList.remove('ready');
    } else if (p.item) {
      const def = ITEM_DEFS[p.item];
      ui.itemIcon.textContent = def.icon;
      ui.itemName.textContent = def.name;
      ui.itemName.classList.add('ready');
      ui.itemSlot.classList.remove('rolling');
      ui.itemSlot.classList.add('ready');
    } else {
      ui.itemIcon.textContent = '?';
      ui.itemName.textContent = 'NO ITEM';
      ui.itemName.classList.remove('ready');
      ui.itemSlot.classList.remove('rolling', 'ready');
    }

    this.minimapAccum += dt;
    if (this.minimapAccum > 0.06) {
      this.minimapAccum = 0;
      this.#drawMinimap();
    }
  }

  #drawMinimap() {
    const canvas = this.ui.minimap;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    const w = canvas.width;
    const h = canvas.height;
    const pad = 12;
    const fw = w - pad * 2;
    const fh = h - pad * 2;
    ctx.clearRect(0, 0, w, h);

    ctx.fillStyle = 'rgba(3,10,17,0.85)';
    ctx.fillRect(0, 0, w, h);

    const toX = (x) => pad + ((x + FIELD.halfW) / (FIELD.halfW * 2)) * fw;
    const toY = (z) => pad + ((z + FIELD.halfL) / (FIELD.halfL * 2)) * fh;

    ctx.fillStyle = 'rgba(15,38,48,0.8)';
    ctx.fillRect(pad, pad, fw, fh);
    ctx.strokeStyle = 'rgba(140,210,240,0.35)';
    ctx.lineWidth = 1;
    ctx.strokeRect(pad, pad, fw, fh);

    ctx.strokeStyle = 'rgba(140,210,240,0.18)';
    ctx.beginPath();
    ctx.moveTo(pad, h / 2);
    ctx.lineTo(w - pad, h / 2);
    ctx.stroke();
    ctx.beginPath();
    ctx.arc(w / 2, h / 2, fw * 0.19, 0, Math.PI * 2);
    ctx.stroke();

    // goal mouths
    ctx.fillStyle = 'rgba(49,184,255,0.9)';
    ctx.fillRect(toX(-FIELD.goalHalfW), h - pad - 4, ((FIELD.goalHalfW * 2) / (FIELD.halfW * 2)) * fw, 4);
    ctx.fillStyle = 'rgba(255,122,36,0.9)';
    ctx.fillRect(toX(-FIELD.goalHalfW), pad, ((FIELD.goalHalfW * 2) / (FIELD.halfW * 2)) * fw, 4);

    // item boxes
    for (const box of this.itemBoxes) {
      if (!box.active) continue;
      ctx.fillStyle = 'rgba(255,208,94,0.85)';
      ctx.fillRect(toX(box.group.position.x) - 1.5, toY(box.group.position.z) - 1.5, 3, 3);
    }
    // boost pads
    for (const pad of this.boostPads) {
      if (!pad.active) continue;
      ctx.fillStyle = pad.big ? 'rgba(255,170,40,0.9)' : 'rgba(255,208,94,0.45)';
      ctx.beginPath();
      ctx.arc(toX(pad.x), toY(pad.z), pad.big ? 2.6 : 1.5, 0, Math.PI * 2);
      ctx.fill();
    }

    // cars
    for (const car of this.cars) {
      const x = toX(car.pos.x);
      const y = toY(car.pos.z);
      if (car.isPlayer) {
        ctx.strokeStyle = 'rgba(255,255,255,0.9)';
        ctx.lineWidth = 1.5;
        ctx.beginPath();
        ctx.arc(x, y, 5.6, 0, Math.PI * 2);
        ctx.stroke();
      }
      ctx.fillStyle = car.team === 'blue' ? '#4fcaff' : '#ff9147';
      ctx.beginPath();
      ctx.arc(x, y, car.isPlayer ? 3.8 : 3.1, 0, Math.PI * 2);
      ctx.fill();
    }

    // ball
    const bx = toX(this.ball.pos.x);
    const by = toY(this.ball.pos.z);
    const glow = ctx.createRadialGradient(bx, by, 0, bx, by, 8);
    glow.addColorStop(0, 'rgba(255,255,255,1)');
    glow.addColorStop(0.4, 'rgba(220,248,255,0.8)');
    glow.addColorStop(1, 'rgba(180,240,255,0)');
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(bx, by, 8, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = '#ffffff';
    ctx.beginPath();
    ctx.arc(bx, by, 2.6, 0, Math.PI * 2);
    ctx.fill();
  }

  #resize() {
    this.camera.aspect = window.innerWidth / window.innerHeight;
    this.camera.updateProjectionMatrix();
    this.renderer.setPixelRatio(Math.min(window.devicePixelRatio || 1, 1.75));
    this.renderer.setSize(window.innerWidth, window.innerHeight);
  }
}

